import { documentedVersion } from './site-config.mjs';
// Callout kinds, by what happens to a reader who ignores the sentence:
// warning - a silently invalid result, lost data or a false belief, with nothing to stop it;
// caution - a recoverable problem the reader or the software will notice;
// check - what to confirm before moving on; note - context that changes no outcome.
const LABELS = {check: 'Check', warning: 'Warning', caution: 'Caution', note: 'Note'};
const callout = (kind, text, title = '', label = LABELS[kind]) => `<aside class="callout callout-${kind}"><p class="callout-label">${label}</p>${title ? `<strong>${title}</strong>` : ''}<p>${text}</p></aside>`;
const check = (text, title) => callout('check', text, title);
const warning = (text, title) => callout('warning', text, title);
const caution = (text, title) => callout('caution', text, title);
const note = (text, title) => callout('note', text, title);
const added = (version, text) => callout('new', text, '', `New in ${version}`);
const table =(rows) => `<table><thead><tr><th>Setting</th><th>What it changes</th><th>When to change it / example</th></tr></thead><tbody>${rows.map(r=>`<tr>${r.map(c=>`<td>${c}</td>`).join('')}</tr>`).join('')}</tbody></table>`;
const grid = (head, rows) => `<table><thead><tr>${head.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(c=>`<td>${c}</td>`).join('')}</tr>`).join('')}</tbody></table>`;
const step = (id,title,action,...callouts) => {
  if (!callouts.length || callouts.some(c => !c.startsWith('<aside class="callout callout-'))) throw new Error(`step ${id} needs typed callouts`);
  return `<h2 id="${id}">${title}</h2><p>${action}</p>${callouts.join('')}`;
};
const imageFigure = (file,title,alt,caption) => `<figure data-image-title="${title}"><img src="assets/images/${file}" alt="${alt}"><figcaption>${caption}</figcaption></figure>`;
const term = name => `<button class="term" data-term="${name}">${name}</button>`;
export const glossary = {
  'FASTQ':'A sequencing-read file containing nucleotide sequences and a quality score for each base.',
  'Count matrix':'A gene-by-sample table of unnormalized read or fragment counts. TPM, FPKM and log-transformed values are not raw counts.',
  'Contrast':'The comparison being estimated, including its factor, numerator and denominator. Positive log2 fold change means higher expression in the numerator.',
  'Adjusted p-value':'A p-value adjusted for multiple testing. An FDR threshold concerns the expected proportion of false discoveries among a called set under the method assumptions; it is not the probability that one gene is false.',
  'log2 fold change':'An effect size on a base-two logarithmic scale. +1 represents a twofold ratio; -1 represents half the expression relative to the denominator.',
  'Covariate':'A recorded sample characteristic included in a statistical model, such as batch or donor.',
  'PCA':'Principal component analysis: a low-dimensional view of major variation among samples. Separation is a diagnostic observation, not proof of a treatment effect.',
  'Gene identifier':'The label used to identify a gene in a database. Symbols, Ensembl IDs and NCBI GeneIDs are different identifier namespaces.',
  'Enrichment':'A test asking whether genes associated with a function are over-represented in a selected set or concentrated in a ranked list.',
  'WSL2':'Windows Subsystem for Linux 2, the Linux environment used to run this application’s analysis tools on Windows.',
  'Biological replicate':'An independently sampled biological unit. Repeated measurements or sequencing lanes of one unit do not create independent biological replicates.',
  'Strandedness':'Whether a sequencing library preserves the orientation of the original RNA and how that orientation relates to aligned reads.',
  'Universe':'The background genes eligible for an over-representation analysis. Its definition changes the enrichment comparison.',
  'GSEA':'Gene set enrichment analysis, which evaluates gene sets against a ranked gene list.',
  'GSVA':'Gene set variation analysis, used here to produce descriptive pathway-activity scores for individual samples.',
  'Provenance':'The recorded inputs, versions, parameters and processing steps needed to establish how an output was produced.'
};
export const pages = [
{slug:'index',title:'BulkSeq Studio handbook',group:'Start here',summary:'From your starting data to a reviewable analysis, one decision at a time.',body:``},
{slug:'guide',title:'Install and first run',group:'Start here',summary:'Prepare the desktop application and the analysis environment.',body:`<p>Before you start, identify your operating system and arrange enough local storage for tools, reference files, reads and results. Storage requirements depend on the study; the tool installation alone is not a complete disk budget.</p>${step('download','1. Download a release','Open the <a href="https://github.com/tunabirgun/bulkseq-studio/releases/latest">official release page</a>. The published baseline supplies a Windows installer or portable ZIP, and a Linux x86_64 AppImage or portable archive. Select the matching package and verify its SHA-256 against the release’s SHA256SUMS.txt.',check('Check the package platform and release notes.'),caution('Close an existing application before running the Windows installer.'))}<pre><code>Get-FileHash FILE -Algorithm SHA256</code></pre><p>On Linux, make the downloaded AppImage executable with <code>chmod +x FILENAME.AppImage</code>. The AppImage needs glibc 2.38 or newer: its bundled graphics and audio libraries require GLIBC_2.38 symbols, so Ubuntu 22.04, Debian 12 and Red Hat Enterprise Linux 9 are too old for it.</p>${note('The Windows installer and portable build are not code-signed, so Windows SmartScreen can show an unrecognised-publisher warning before the first launch. The SHA-256 comparison above is the integrity check.')}${step('environment','2. Complete Environment setup','Open the app and let the first-run Environment setup check the GUI packages, WSL2 on Windows, core bioinformatics environment and R/DESeq2 stack. It names the phase it is running — the WSL distribution, the bioinformatics tools, then the R and Bioconductor load test, which can take about two minutes on the first run after an update. Work through Action needed entries, then click Re-check. Show details / log exposes installation failures. Its persistent setup log is stored in your user application-data directory rather than the installed or portable application folder, so it remains available when bundled files are read-only.',check('Read statuses against the installed profile. If tool, R or import verification fails, setup can make one in-place repair using the same installed specification, then rechecks it. Post-link steps can redownload required files; an unresolved verification failure remains failed.'),caution('A core-only installation can mark full-only tools not applicable; choose Install full R/DESeq2 stack when your intended analysis needs it.'))}<p>Setup reports its result in Show details / log as <em>WSL bioinformatics installer finished with exit code N</em>. <a href="codes.html#setup">Exit codes and statuses</a> says what each code means and what to do.</p><h2 id="installation-choices">Choices that matter</h2>${table([['Installer or portable package','Changes how the application is installed, not your scientific model.','Use portable when you need an extracted application directory; keep projects separate from application files.'],['Full analysis environment','Adds the R/Bioconductor analysis and figure tools.','A ready interface alone does not establish that differential-expression tools are ready.'],['WSL2 on Windows','Runs Linux analysis tools behind the desktop window.','Enabling the Windows feature may require administrator rights and a reboot. Later environment installation runs in your WSL user account.']])}<p>The full environment specification declares six fewer R packages than 0.30.1 — biomaRt, ComplexHeatmap, EnhancedVolcano, ggtext, ggraph and tidygraph — because no workflow script loads them. A new installation is that much smaller; an environment installed earlier keeps them until it is rebuilt, and no analysis output depends on either state. The running application version is shown at the right of the status bar, so a bug report can name it without opening About.</p>${step('first-project','3. Create a project','Continue to <a href="project.html">Project and sample sheet</a>. You may prepare metadata while tools install, but starting a pipeline requires its applicable tools.',check('Reopen Check Environment from Project if readiness is uncertain.'),caution('Do not repeatedly rebuild an environment without reading the failed setup log.'))}<details><summary>Advanced: Windows resource limits</summary><p>WSL2 may have a lower RAM cap than Windows. Use Edit WSL2 memory / CPU limits on Compute resources and apply the requested restart only after other WSL work is safely stopped. See <a href="resources.html">compute resources</a>; do not copy a large memory allocation from another computer.</p></details>`},
{slug:'inputs',title:'Choose an input route',group:'Project and data',summary:'Use the route that matches the measurements you actually have.',body:`<p>Before importing, establish whether your file contains reads, raw counts, normalized microarray intensities or results from a fitted model. Similar-looking tables can represent different quantities.</p><h2 id="five-routes">Five ways in</h2>${table([['Public accessions','Fetches public metadata and reads, then runs the read-processing route.','Use SRR / SRP / PRJ accessions, or an RNA-seq GSE resolved to SRA runs.'],['Local FASTQ','Skips public download; retains read QC, alignment/quantification and modelling.','Use when reads are already on disk. One run must have one read layout.'],['Count matrix','Skips download, read QC, alignment and counting; fits a count model.','Use raw unnormalized counts, not TPM, FPKM or log-CPM.'],['Imported differential-expression results','Skips local count modelling and uses the supplied statistics.','Confirm the source direction; see <a href="imported-results.html">imported results</a>.'],['Microarray','Uses processed intensities or supported Affymetrix CEL processing, then limma.','Use the Microarray tab, not the raw-count importer.']])}${step('select-route','1. Select the route on Add data','The route tabs are Public accessions, Local FASTQ, Count / DE tables and Microarray. The Count / DE tables tab contains two distinct import buttons.',check('Check the quantity in the file, not just its extension. TSV and CSV can hold either counts or a finished results table.'))}<h2 id="raw-reads">2. Add public or local reads</h2><p>For public data, paste accessions and click Fetch metadata &amp; build samples. Review the inferred layout, FASTQ URLs, read counts and suggested condition labels. For local reads, click Select FASTQ Files and verify that the first and second mates belong to the same biological sample. Missing or swapped mates are not repaired by an aligner setting.</p>${caution('Single-end and paired-end reads are supported, but a mixed-layout sheet is rejected.')+check('Public metadata suggestions are starting values: verify treatment, controls and replicate identity from the study.')}<h2 id="counts">3. Import counts when counting is complete</h2><p>Click Import count matrix. Supply a gene-by-sample table, with sample columns that can be matched to the sample sheet. Every cell must be present, numeric, finite and non-negative. Raw integer counts are the default requirement. Any non-integer value triggers the explicit RSEM/tximport estimated-count prompt; accepted estimates are rounded with round-half-to-even. This opt-in is not permission to import normalized abundances.</p>${added('0.32.0','Validation now occurs before the interface copies the table and again before the workflow writes count outputs. A column total near one million raises a normalized-data suspicion warning but does not prove the table is TPM. The corrected contract has synthetic regression coverage; historical benchmark claims have not yet been reproduced under 0.32.0.')} ${note('A count of 120 reads is a raw observation. TPM 12.5 is a normalized abundance, even if rounding would turn it into an integer.','Illustrative example')+warning('Rounding TPM does not recover counts.')}<h2 id="next">4. Verify the imported samples</h2><p>Open <a href="project.html">Samples</a>, inspect every row, save the sheet and select the organism on <a href="references.html">Reference</a>. For intensities follow <a href="microarray.html">Microarray input</a>; for finished statistics follow <a href="imported-results.html">Imported results</a>.</p><details><summary>Troubleshooting: a table is rejected</summary><p>Check delimiters, unique gene identifiers, missing cells, finite non-negative numeric values and sample-column names. Do not suppress a format error by changing the biological meaning of the data. Export a plain TSV/CSV from the upstream tool and retain its original file and method record.</p></details>`}
];
pages.push(
{slug:'project',title:'Project and sample sheet',group:'Project and data',summary:'Connect every data file to the biological sample and group it represents.',body:`<p>Before you start, prepare a sample inventory from your laboratory records. Each biological replicate needs a stable identifier, a condition and the correct input files or matrix column.</p>${step('create','1. Create or open a project','On Project, choose a new local project folder. The application writes configuration under config/, copies its workflow and records a provenance manifest. On Windows, Use WSL filesystem places the project on the Linux filesystem; ordinary network shares are refused.',warning('Keep the project apart from the installed application.'),check('Confirm the selected drive has room for intermediate files, not just the final tables.'))}${step('samples','2. Review the Samples table','Open Samples after adding data. Inspect sample names, condition labels and read layout. Expand More table tools to add rows or columns, or use Import table… for TSV, CSV or XLSX metadata. Match matrix columns exactly; do not assume table order identifies the samples.',warning('A suggested group from public metadata is not a verified biological label.'),check('Confirm it against the study design and correct missing or ambiguous values.'))}<h2 id="columns">Columns that determine the analysis</h2>${table([['condition','Defines the groups used by the default comparison.','Illustration: use treated and control consistently, not a mixture of Control, control and untreated for the same group.'],['dataset','Identifies independent studies for multi-study analysis.','Use study_A and study_B for distinct studies, not sequencing lanes from one sample.'],['batch / donor / other covariates','Can enter the model to account for recorded sample structure.','Use b1 and b2 for categorical batches. Purely numeric 1 and 2 are fitted as a continuous trend.'],['File paths / sample identifiers','Connects observations to their metadata.','A renamed matrix column must still match its intended sample. Do not move an input after validation without rechecking.']])}<h2 id="library-name">Naming a library</h2><p>The sheet may also carry an optional <code>library_name</code> column directly after <code>sample_id</code>: the submitter&#39;s own label for the sequencing library. An import by accession fills it from the archive&#39;s record where one exists and leaves it empty otherwise; you can type or change it like any other column. It is descriptive, so it may be left blank and two rows may share a name.</p><p><code>sample_id</code> stays the identifier the analysis runs on. File names, matrix columns, results tables and every match between a sample and its data use it, and nothing is derived from the library name, which is why duplicates are safe. Where a human-readable name helps, the run summary, the study design and the report show it beside the sample identifier rather than instead of it, and per-sample figure labels use it, adding the sample identifier only for rows whose name repeats so that no two points on a plot carry the same label. Because it names a sample rather than describing a condition, it is not offered as a design covariate and the covariate screen does not test it. A project whose sheet has no such column is unaffected, and its sheet is not rewritten to add an empty one.</p>${step('save','3. Save the sheet','Click Save samples.tsv, then continue to the <a href="design.html">design and contrast</a>. Changes in group membership or covariates can change the fitted comparison; they are analysis changes, not cosmetic labels.',check('Count independent biological replicates.'),warning('Technical repeats do not supply independent replication; no software setting can recover missing experimental replication.'))}<details><summary>Advanced: preserving a project</summary><p>Retain config/, logs/, checks/ and the applicable result files together. The active workflow may be synchronized when a project made by an older application runs again; record the software version and preserve the original project before an update intended to reproduce an older result.</p></details><details><summary>Advanced: start from a bundled example study</summary><p>Create Benchmark Project on the Project page configures a project for one of the bundled public studies, as a worked example or an end-to-end check of an installation. Read-based examples download their reads on the first run, so they need network access and disk space; the microarray examples fetch processed intensities instead.</p><table><thead><tr><th>Bundled study</th><th>Route and samples</th><th>Comparison</th></tr></thead><tbody><tr><td>Pasilla paired-end subset, <em>Drosophila melanogaster</em> (GSE18508)</td><td>Public paired-end reads, 4 samples</td><td>CG8144 RNAi against untreated</td></tr><tr><td>Yeast rpd3-delta Ume6 truncation subset, <em>Saccharomyces cerevisiae</em> (PRJNA630199)</td><td>Public paired-end reads, 4 samples</td><td>Ume6 delta2-508 against the rpd3-delta control</td></tr><tr><td>Rice CY1000 salt stress, <em>Oryza sativa</em> Japonica Group (PRJDB38133)</td><td>Public paired-end reads, 6 samples</td><td>5-day NaCl stress against control</td></tr><tr><td>Arabidopsis hub2-3 mutant, ATH1 array (GSE30735)</td><td>Microarray intensities, 6 samples</td><td>hub2-3 against Col-0 wild type</td></tr><tr><td>Yeast cbc2-delta, YG-S98 array (GSE6705)</td><td>Microarray intensities, 6 samples</td><td>cbc2-delta against wild type</td></tr><tr><td><em>Fusarium graminearum</em> PH-1 spores against mycelium (GSE55477, PRJNA239711, SRP039087)</td><td>Public paired-end reads, 6 samples, 90 bp mates, unstranded</td><td>spores against mycelium</td></tr><tr><td><em>Fusarium graminearum</em> Z-3639 heat shock (GSE78885, PRJNA314297, SRP071140)</td><td>Public paired-end reads, 6 samples, 151 bp mates, reverse-stranded</td><td>37&nbsp;°C against 25&nbsp;°C</td></tr></tbody></table><p>The two <em>Fusarium</em> studies were added in 0.31.0. The spores-against-mycelium study is the fungal example used as a guardrail; its dataset publication is Zhao et al. (2014) <em>BMC Genomics</em> 15:191, <a href="https://doi.org/10.1186/1471-2164-15-191">doi:10.1186/1471-2164-15-191</a>, not the PH-1 genome paper. The heat-shock study sequenced strain Z-3639 and is analysed against the PH-1 reference preset, and its reverse-stranded library exercises a different counting orientation. The differential-expression counts the catalogue records for both studies were first obtained in the 0.2x-era runs and reproduced from FASTQ under the 0.31.0 workflow, each count matrix and DESeq2 table identical to a v0.29.1 run of the same reads.</p></details>`},
{slug:'imported-results',title:'Import finished differential-expression results',group:'Project and data',summary:'Reuse external statistics without claiming a local model was fitted.',body:`<p>Before you start, obtain the complete upstream differential-expression table and its methods: organism, identifier type, numerator, denominator, model, adjustment method and shrinkage where known.</p>${step('import','1. Import the complete results table','On Add data → Count / DE tables, choose Import differential-expression results. A supported gene-ID column, log2FoldChange and an adjusted-p column are required. The importer checks the complete table, including safe unique identifiers, numeric ranges and supplied statistic direction.',warning('Do not upload only selected hits if you intend to interpret tested-gene backgrounds or ranked analyses as if the complete tested set were available. Retain the upstream full results and record any filtering.'))}<h2 id="direction">2. Confirm the source direction</h2><p>Confirm the numerator and denominator used by the upstream software. Positive ${term('log2 fold change')} means higher expression in that numerator. Local contrast controls do not reverse or reinterpret an imported table.</p>${table([['Source numerator / denominator','Determines how up and down are described.','Illustration: treated/control with +1 means a twofold higher expression ratio in treated. Reversing the comparison changes the sign.'],['Upstream method metadata','Controls what the report can truthfully attribute to the source analysis.','Leave an unknown p-adjustment method unknown; do not label it Benjamini–Hochberg by assumption.'],['alpha and |log2FC|','Selects direction-split gene lists from the supplied values.','A stricter alpha can reduce selected genes without refitting the upstream model.'],['Organism / identifier namespace','Controls downstream gene mapping.','A table of symbols needs compatible annotation settings; choosing a species cannot translate an unrelated ID namespace automatically.']])}${step('integrity','3. Preserve and check the import','The project copy is bound to its SHA-256, size, row count and schema. Keep that copy intact; changes require renewed validation. Review applicable enrichment, figures and network outputs after running.',check('No FASTQ processing, alignment, counts or local DESeq2 fit occurs. Reports must describe an imported-results route.'))}<h2 id="outputs">What can be produced</h2><p>Applicable outputs include volcano and p-value views, an MA view when the required mean-expression information exists, enrichment, STRING networks, set overlap and a preranked .rnk file. Imported ranking uses confirmed log2FoldChange rather than an upstream statistic of undocumented scale.</p>${note('A results-only table has no per-sample expression matrix. It cannot provide count heatmaps, PCA, sample correlations, normalized-expression exports or the matrix-based Wilcoxon check. The missing outputs are not an installation fault.')}<details><summary>Troubleshooting: the statistic sign is rejected</summary><p>Check the upstream export and column alignment. A shifted delimiter can put unrelated numbers into the statistic column. Do not flip a statistic merely to pass import; establish its definition and source direction first.</p></details>`},
{slug:'microarray',title:'Microarray input',group:'Project and data',summary:'Bring GEO or local expression intensities into the limma route.',body:`<p>Before you start, identify the array platform and whether intensities have already been normalized and log2 transformed. RNA-seq counts and microarray intensities need different input routes.</p>${step('source','1. Choose a source','On Add data → Microarray, enter a GEO GSE accession or choose Import microarray matrix for a local table. An RNA-seq GEO series belongs on the public-read route and is redirected to SRA.',warning('For a local file, use a gene-by-sample TSV or CSV with gene IDs/symbols in the first column and already-normalized log2 intensities in sample columns.'))}<h2 id="processing">2. Set processing deliberately</h2>${table([['GEO series matrix (default)','Uses the submitter-normalized matrix rather than reprocessing raw arrays.','Choose when the deposited processing matches your planned analysis; read the GEO processing description.'],['Affymetrix raw CEL → RMA','Reprocesses supported raw Affymetrix arrays with RMA.','Use when intentionally re-normalizing available CEL files; this is not a generic raw-format importer for every array platform.'],['Log2 transform: auto / force / off','Controls whether intensities are transformed. Double transformation distorts their scale.','Illustration: an intensity 256 becomes 8 after log2. If values are already log2 intensities, another log2 is not the same analysis.'],['Local matrix','Uses your processed intensities without a GEO download.','Confirm preprocessing with whoever supplied the matrix; a plausible-looking number range is not full provenance.']])}${step('metadata','3. Review sample groups and identifiers','Fetched GEO arrays map probes to gene symbols; the platform accession is recorded. For a local gene matrix, ensure identifiers match the selected organism. Review condition labels and build the comparison on Samples and Analysis settings.',caution('Use dot decimal separators. Blank or NA can represent missing values; text placeholders and comma-decimal numbers are refused rather than silently converted.'))}<h2 id="result">4. Run and review array-specific checks</h2><p>The route fits limma and writes a common differential-expression table schema. That filename/schema does not mean DESeq2 was fitted. Inspect normalization and probe-mapping checks before interpreting downstream figures or enrichment. There is no FASTQ, alignment or RNA-seq read-count QC for this route.</p><details><summary>Advanced: design limits in the published baseline</summary><p>Microarray limma supports the documented additive design route. Interaction and nesting operators are rejected in the published baseline; do not assume the same design capabilities as DESeq2. See <a href="design.html#advanced-design">advanced design</a>.</p></details>`}
);
pages.push(
{slug:'references',title:'Select a reference',group:'Analysis setup',summary:'Match the organism, assembly, annotation and gene identifiers.',body:`<p>Before you start, identify the organism and, for read analysis, the intended genome assembly and annotation. A reference determines where reads can map and what the workflow counts as a gene.</p>${step('preset','1. Choose an organism preset','Open Reference, select an organism and click Use Selected Preset. The preset supplies genome/annotation resources and downstream organism settings where supported. Imported tables still need the correct organism and identifier mapping even though they do not align reads.',check('Confirm organism and strain where relevant.'),warning('A related species is not an interchangeable replacement for a missing annotation.'))}<h2 id="choices">Reference choices and their consequences</h2>${table([['Genome FASTA','Provides the sequence against which reads are aligned or a transcriptome is generated.','Use the assembly for your experiment; a different assembly can change mappings and counts.'],['Annotation GTF/GFF3','Defines gene/transcript features and identifiers.','Use an annotation compatible with the FASTA. Matching species names alone do not prove matching assemblies or chromosome names.'],['Organism enrichment settings','Select annotation databases, KEGG organism and STRING taxon.','Use the organism represented by your data. Incorrect species settings can produce missing or misleading mappings.'],['Identifier namespace','Determines how result rows join annotation records.','Symbols, Ensembl IDs and NCBI GeneIDs are not interchangeable strings. Confirm the namespace of imported tables and custom sets.']])}${step('custom','2. Supply a custom reference when needed','Use a custom genome and annotation if the catalog does not supply your required assembly. Keep the original source URL, version and integrity information.',warning('Reference validation checks FASTA/annotation consistency on raw-read routes before indexing; inspect failures instead of changing chromosome labels blindly.'))}<details><summary>Advanced: reuse a prebuilt index</summary><p>The Reference page does not expose the prebuilt index fields in the published baseline. Set <code>reference.star_index</code> or <code>reference.salmon_index</code> to an existing directory; <code>reference.hisat2_index</code> is the hisat2-build prefix, not an individual index file. An optional <code>reference.transcriptome_fasta</code> supplies Salmon’s index input.</p><pre><code>bulkseq config set reference.star_index PATH</code></pre><p>A missing configured path is refused rather than silently rebuilt. The genome/annotation check still applies with prebuilt indexes. Salmon still derives its transcript-to-gene map from the annotation; transcript names in an external index must agree with that map. A protein FASTA is not an active substitute.</p></details><h2 id="mapping-problems">Troubleshooting: no enrichment mappings</h2><p>Check species and identifier namespace before interpreting an empty table biologically. Missing OrgDb support does not automatically disable all enrichment: available KEGG, g:Profiler and STRING routes have their own organism coverage and connectivity requirements. See <a href="enrichment.html">enrichment and networks</a>.</p>`},
{slug:'analysis',title:'Read processing and analysis settings',group:'Analysis setup',summary:'Know which controls affect measurements, models and optional outputs.',body:`<p>Analysis settings contains Comparison, Read processing, Output options and Advanced tabs. Inactive controls follow the input route: a count table does not undergo trimming, and imported results do not fit a local differential-expression engine.</p>${step('processing','1. Choose read processing','For FASTQ/public-read routes, keep the documented fastp trimming default unless your protocol requires another supported trimmer or the input is already trimmed. Raw and post-trimming FastQC reports feed MultiQC.',check('Record any deliberate departure from defaults.'),warning('A different trimmer or aligner can change retained reads and gene counts even when outputs use compatible formats.'))}<h2 id="core-controls">Core controls</h2>${table([['Trimming: on; fastp default','Removes adapter/low-quality sequence before alignment. Trim Galore and Trimmomatic are alternatives.','Disable only when intentionally using already-trimmed reads. Keep the upstream trimming record.'],['rRNA filtering: off; SortMeRNA selected','Removes reads classified as ribosomal RNA before alignment when enabled.','Enable to implement a planned rRNA-removal step. SortMeRNA uses a database; RiboDetector is a CPU classifier without that reference database.'],['FastQ Screen: off','Reports matches to an existing genome panel; it is a screen, not a contamination-removal filter.','Enable with a configured panel to inspect unexpected sources. No genome panel is downloaded automatically.'],['Aligner: STAR','STAR and HISAT2 provide genome BAMs; Salmon performs transcriptome quantification without BAMs.','Consider HISAT2 or Salmon when resource constraints and the analysis goal warrant them. Changing the route can change estimated counts.'],['Quantifier: featureCounts','Counts annotated features from genome alignments. STAR gene-counts is an alternative with STAR; HISAT2 uses featureCounts and Salmon uses tximport.','Use STAR gene-counts only when you intentionally choose STAR’s counting definition.'],['RSeQC: off','Adds read-distribution and gene-body coverage diagnostics from BAMs.','Enable on STAR/HISAT2 when you need those views; it cannot run on Salmon output.'],['Organellar genes: keep','Keep includes them; discard removes them before DE; separate runs nuclear DE and writes organellar counts/fractions.','For a planned nuclear-only comparison, choose discard or separate and record the choice. Separate does not promise a separate organellar DE fit.']])}<h2 id="advanced-reads">2. Understand advanced read parameters</h2><details><summary>Advanced: trimming settings with examples</summary>${table([['fastp quality Phred 15; low-quality limit 40%','Controls the quality classification and tolerated fraction of low-quality bases.','Raise stringency only with a protocol/QC reason; stricter filtering can lose usable reads as well as poor reads.'],['Minimum length 36','Rejects reads shorter than the retained-length requirement.','Illustration: a 30-base read fails 36. Raising the limit to 50 also removes a 45-base read.'],['Poly-G off; poly-X off','Enables terminal homopolymer trimming.','Use when library/instrument characteristics justify it, not to make a QC panel appear cleaner.'],['Trimmomatic window 4, quality 15; leading/trailing 3','Sets sliding-window and end-quality trimming.','A stricter window criterion can shorten more reads; preserve the reason for the change.'],['RiboDetector ensure=norrna; chunk size 256 × 1024 reads','Sets classification retention mode and processing batch size.','Change chunk size for memory constraints; it is not a biological significance threshold.'],['FastQ Screen subset 100000; panel config required','Controls how many reads are sampled and which genomes are screened.','A larger screen samples more reads but costs time; an absent organism in the panel cannot be detected by that panel.']])}</details><details><summary>Advanced: alignment and counting settings</summary>${table([['STAR two-pass off','Controls a second alignment pass informed by detected splice junctions.','Enable for an intentional alignment protocol, then treat outputs as a changed analysis.'],['STAR maximum multimappers 10; mismatch/read-length ratio 1.0','Constrains reported mapping multiplicity and mismatch acceptance.','Tighter constraints may reduce assigned reads; do not tune solely to increase a downstream hit count.'],['featureCounts feature exon; attribute gene_id','Defines the annotation features and grouping key counted as genes.','A custom annotation must actually contain the chosen fields. Changing exon to another feature changes the quantified object.']])}<p>Strandedness is inferred and applied per sample in the published baseline. Inspect <code>results/aligned/strandedness_per_sample.tsv</code>; a configured generic code is not evidence that every library has that orientation.</p></details>${step('save-settings','3. Save the settings','Click Save analysis settings. Complete <a href="design.html">Comparison</a>, then choose <a href="resources.html">resources</a> and run <a href="checks.html">pre-run checks</a>.',caution('Changing processing after a validation pass invalidates the saved run state; validate the actual final configuration.'))}`},
{slug:'design',title:'Design, contrast and thresholds',group:'Analysis setup',summary:'Specify the biological question before choosing the called gene set.',body:`<p>Before you start, write the comparison in one sentence and identify the independent biological replicates. A model cannot separate treatment from batch if every treated sample is in one batch and every control is in another.</p>${step('contrast','1. Set the factor and direction','On Analysis settings → Comparison, choose the factor, numerator and denominator from the saved sample metadata. The default formula is ~ condition.',check('Read the contrast aloud: numerator compared with denominator. For treated/control, positive log2 fold change means higher expression in treated. Imported-results direction is confirmed at import instead.'))}<h2 id="thresholds">2. Choose calling thresholds</h2>${table([['alpha: 0.05','The adjusted-p threshold used in the selected gene lists. Smaller values impose a stricter evidence cutoff.','Illustration: padj 0.03 with log2FC 1.2 passes the default cutoffs but fails alpha 0.01. This is not a 3% probability that this gene is false.'],['|log2FC|: 1','Requires a minimum absolute effect size as well as the adjusted-p criterion. A value of 0 disables the fold-change filter.','Illustration: +1 means twofold; -1 means half relative to the denominator. Raising the cutoff can exclude modest effects with strong statistical evidence.'],['DE engine: DESeq2','Chooses the count-model analysis. limma-voom and edgeR quasi-likelihood are documented alternatives; microarrays use limma.','Use a preselected analysis strategy. Changing engines is a new model analysis, not just a figure style change.'],['DESeq2 minimum count: 10','Controls low-count filtering before model fitting.','Review low-count treatment for your study rather than repeatedly changing it to obtain more hits.'],['Shrinkage: apeglm','Regularizes effect-size estimates; ashr and normal are supported alternatives.','Use a justified estimator. The published volcano and direction lists use unshrunken effects; shrinkage is not the volcano x-axis setting.']])}${warning('Not significant does not establish no change. Equivalence testing asks a different question with an explicit effect-size margin; its applicability is route-specific. A statistically selected gene set is not by itself a causal or clinical conclusion.','Interpretation')}<h2 id="covariates">3. Include justified covariates</h2><p>Use Design helper to select relevant sample columns and build an additive formula, such as <code>~ batch + condition</code>. This estimates the condition comparison while modelling recorded batch structure. It does not erase confounding or manufacture information.</p>${table([['Reference level','Determines the baseline level used in model coding.','Use a biologically meaningful baseline and inspect the explicit numerator/denominator rather than relying only on level order.'],['Text batch labels b1 / b2','Represents distinct categories.','Use for two sequencing batches.'],['Numeric covariate 1 / 2 / 3','Fits a continuous linear trend rather than separate categories.','Use only if a numeric trend is intended; for numbered batches, use text labels.'],['Additional covariates','Changes the fitted adjustment and consumes model information.','Include measured, relevant factors; adding every column is not automatically better.']])}${step('check-design','4. Save and validate','Save settings and run the <a href="checks.html">input/design checks</a>. Review rank and replication warnings and investigate any aliased factors.',warning('Do not resolve an unidentifiable design by renaming levels. The experimental structure must support the requested comparison.'))}<details><summary id="advanced-design">Advanced: interactions and model scope</summary><p>DESeq2 can fit a typed interaction, but the contrast picker reports a two-level factor contrast at the other factor’s reference level, not the interaction coefficient. The design check (08) reports review-required for such a design, naming the coefficient actually tested and stating that it is the contrast at the reference level of the remaining factors; the fit is not refused, and an explicit contrast or coefficient is the way to test the interaction itself. The alternative count engines and microarray limma reject interaction/nesting operators <code>:</code>, <code>*</code>, <code>^</code> and <code>/</code>. Do not read that contrast as an interaction test.</p><p>The output-stage covariate screen reads the PCA coordinates each locally fitted engine writes, so it runs on DESeq2, edgeR, limma-voom and microarray limma and is skipped only for imported results, which have no expression matrix. Because every engine screens its own coordinates, the same column can be reported differently on different engines. The screen is advisory and does not add terms automatically. See <a href="checks.html#output-checks">output checks</a>.</p></details><p>Method reference: <a href="https://bioconductor.org/packages/release/bioc/vignettes/DESeq2/inst/doc/DESeq2.html">DESeq2 vignette</a>.</p>`}
);
pages.push(
{slug:'resources',title:'Compute resources',group:'Analysis setup',summary:'Set feasible CPU, memory and storage budgets before execution.',body:`<p>Before you start, close unnecessary memory-heavy applications and check free storage. Raw reads, reference indexes, BAMs and temporary files can greatly exceed the final results folder.</p>${step('detect','1. Detect available resources','On Compute resources, click Detect and Recommend. Review the proposed profile and resource values, then click Save Resources.',caution('A recommendation is a starting allocation for this machine, not a guarantee that every genome or study fits.'),check('On Windows, check the RAM available inside WSL2 as well as the Windows total.'))}<h2 id="resource-settings">What resource settings change</h2>${table([['Profile: balanced / low / high / custom','Chooses a resource allocation strategy.','Use a conservative profile when sharing the computer; custom requires a budget you can support.'],['CPU / threads','Limits computational parallelism.','More threads may shorten parallel steps, but do not multiply RAM capacity or speed every step equally.'],['Memory budget','Constrains local job scheduling and must fit available RAM.','Leave room for the operating system and other processes. Assigning 32 GB on a 16 GB machine does not supply memory.'],['WSL2 memory / CPU limits','Caps Linux resources on Windows.','Raise a restrictive cap only within host capacity and apply the required WSL restart safely.'],['Aligner selection','Changes memory/storage needs and computational route.','STAR is memory-intensive; HISAT2 and Salmon offer alternative routes. Salmon does not produce BAMs.']])}${step('estimate','2. Inspect the runtime estimate','Open Runtime estimate and click Estimate Runtime after saving inputs, reference and resources. Use it to plan, not as a completion deadline.',note('Downloading, reference indexing, disk speed, concurrent workloads and optional modules affect elapsed time. A new reference can make the first run longer.'))}<h2 id="troubleshooting">If a job is killed or storage fills</h2><p>Read the rule log to distinguish out-of-memory, disk exhaustion and tool errors. Reduce concurrency or choose a justified alternative route only after identifying the cause. Do not repeatedly resume while the same resource shortage remains.</p><details><summary>Advanced: cluster allocations</summary><p>Local CPU/RAM pools are not the same as a scheduler’s per-rule allocation. The published Slurm and Kubernetes profiles avoid a global local-memory pool. Review the generated command and site-specific resources before submission; see <a href="cli.html#hpc">HPC guidance</a>.</p></details>`},
{slug:'checks',title:'Pre-run and result checks',group:'Validate and run',summary:'Separate input readiness, execution success and scientific interpretation.',body:`<p>Before you start, save Samples, Reference, Analysis settings and Resources. A check of an earlier configuration does not certify a later edit.</p>${step('pre-run','1. Validate current inputs','On Pre-run checks, click Validate current run inputs. Read each message and resolve failures involving file paths, schema, contrast levels, reference consistency or design rank.',note('Each check is listed by a plain-language name with the findings it recorded, so a warning can be read on the page instead of only in its JSON file. A completed check records content fingerprints for configuration, sample sheet, local inputs, reference locks and index files.'),caution('Replacing or editing these invalidates the saved pass before launch or resume.'))}<h2 id="statuses">Understand the status</h2>${grid(['Status','Meaning','What to do'],[['FAIL','A condition prevents the requested workflow from proceeding correctly.','Fix the named cause and revalidate. Start is disabled until you do. Do not rename an invalid file to hide its format.'],['REVIEW_REQUIRED','A result or configuration needs interpretation before reliance.','Investigate the evidence, then tick the acknowledgement on Pre-run checks. It is neither a fatal error nor an acceptable result by default.'],['WARNING','An advisory condition may limit interpretation.','Read and record it; a completed run can still have warnings.'],['PASS / not applicable','A specific check passed, or the route does not produce the relevant quantity.','Neither establishes universal validity. A results-only route has no alignment-QC measurement.'],['STALE','Interface only. The saved input validation no longer matches the current configuration, sample sheet or inputs.','Validate again. Start is disabled until the checks match what you saved.']])}<p>The overall status is the most severe finding: FAIL, then REVIEW_REQUIRED, then WARNING, then PASS, with STALE above FAIL in the interface. Three kinds of check can stop a workflow that is already running: a FAIL in check 00, project setup; anything but PASS in check 05, reference validation, on the FASTQ and SRA routes; and a failed microarray import, which records FAIL in checks 11 and 12, including when no probe resolves to one gene. Every other check records its status and the run carries on, so read them when it finishes. <a href="codes.html#statuses">Exit codes and statuses</a> puts these beside the command-line and setup codes.</p>${step('dry-run','2. Inspect the workflow plan','Use Dry Run before Start Run to validate the configured graph and see which steps would execute without running the full analysis.',caution('A dry run does not establish that a scheduler, remote database or large-memory rule will execute successfully.'))}<h2 id="each-check">What each check tests</h2>${grid(['Check','What it tests','Statuses','Stops a running workflow'],[['00 · project setup','Configuration paths and sections, the sample sheet, the design factors against its columns, imported-results provenance, and whether the R packages load.','PASS, WARNING, FAIL','Yes, on FAIL'],['01 · input validation','Required sample-sheet columns, duplicate or unsafe sample names, replicates per condition, and study confounding in a multi-study contrast.','PASS, WARNING, FAIL','No; the interface will not start a run on its FAIL'],['05 · reference validation','Genome and annotation integrity, the counting feature and attribute, and at least 95% agreement between FASTA and annotation sequence names. FASTQ and SRA only.','PASS, FAIL','Yes, on anything but PASS'],['06 · alignment','Each sample’s uniquely mapped percentage from STAR or HISAT2.','PASS, WARNING, REVIEW_REQUIRED','No'],['07 · quantification','Each sample’s assigned-read fraction, or its library size for an imported count matrix.','PASS, WARNING, REVIEW_REQUIRED, FAIL','No'],['08 · design','Whether the design matrix is full rank, and interaction terms or numeric covariates that need review.','PASS, REVIEW_REQUIRED, FAIL','No'],['09 · differential expression','Whether any gene reaches the significance threshold; none is REVIEW_REQUIRED.','PASS, REVIEW_REQUIRED','No'],['10 · enrichment','Whether enrichment ran, its annotation coverage, and how well identifiers mapped.','PASS, WARNING, REVIEW_REQUIRED','No'],['11 · normalization','Microarray only: probe count, the normalization applied and the log2 decision.','PASS, WARNING, FAIL','Yes, when the import fails'],['11 · custom enrichment','Only with custom gene sets: whether they overlap the differential-expression genes. Shown on Pre-run checks but missing from <code>sanity_checks.txt</code>.','PASS, REVIEW_REQUIRED','No'],['12 · probe mapping','Microarray only: the fraction of probes that resolve to exactly one gene; below half is REVIEW_REQUIRED, none is FAIL.','PASS, REVIEW_REQUIRED, FAIL','Yes, on FAIL'],['13 · equivalence','DESeq2 only: genes statistically equivalent to no change at the configured threshold. Informational.','PASS','No'],['14 · Wilcoxon sensitivity','A rank-sum cross-check of the primary calls, with a warning when the smallest group has fewer than five samples.','PASS, WARNING','No'],['15 · set overlap','Overlap of the differential-expression genes with MSigDB Hallmark sets for the organism.','PASS, REVIEW_REQUIRED','No'],['16 · protein network','Whether a STRING network was built; a STRING or layout failure is a WARNING.','PASS, WARNING','No'],['17 · meta-analysis','Multi-study only: the studies admitted, shared genes and the combined result; FAIL with fewer than two admissible studies or no shared genes.','PASS, REVIEW_REQUIRED, FAIL','No'],['18 · meta-enrichment','Multi-study only: cross-study enrichment and how identifiers mapped to Entrez IDs.','PASS, REVIEW_REQUIRED','No'],['19 · orientation','A contrast whose numerator and denominator look inverted, or an unconfirmed imported-results direction.','PASS, REVIEW_REQUIRED, FAIL','No'],['20 · duplicate study','Multi-study only: studies with identical per-sample read counts or near-identical fold changes, a sign of re-deposited data.','PASS, REVIEW_REQUIRED','No'],['21 · strandedness','Samples in one study that disagree on inferred strandedness, and studies with divergent assignment fractions.','PASS, REVIEW_REQUIRED','No'],['22 · sample structure','Whether replicates cluster more tightly than samples of other conditions.','PASS, WARNING','No'],['23 · covariate structure','Sample-sheet columns outside the design that track PC1 or PC2 beyond chance, or alias the contrast.','PASS, WARNING, REVIEW_REQUIRED','No']])}<p>Checks 22 and 23 use WARNING differently. In check 22 a WARNING means either that replicate structure could not be assessed or that replicates cluster no more tightly than other conditions; only the check file’s <code>assessment</code> field tells the two apart. In check 23 a WARNING always means the screen could not run, and a finding is REVIEW_REQUIRED. Check 08 can list a WARNING message, such as a condition with fewer than two replicates, without that becoming its overall status. Check 01 is written twice with different replicate thresholds: the pre-run check in the interface warns when a condition has fewer than three biological replicates, while the copy the workflow writes when the run starts warns only below two. A design with two replicates per group therefore shows WARNING before the run and PASS in <code>checks/sanity_checks.txt</code> afterwards, although nothing about the design changed.</p><h2 id="output-checks">3. Review checks produced during and after the run</h2><p>Read <code>checks/sanity_checks.txt</code> together with the individual machine-readable checks. Applicability depends on route. Alignment and assignment checks require their corresponding measurements; imported counts receive library-size checks instead of read-assignment fractions.</p><p>Review low mapping, empty/outlying libraries, sample structure, within-study strandedness disagreements and enrichment/network availability. A lack of adjusted-p hits is reported for review; that is not proof of a failed experiment or a reason to relax thresholds automatically.</p><details><summary>Advanced: checks with narrow meanings</summary><p>Check 23 is an <strong>output-stage</strong> screen on every route that fits a local model and writes <code>results/deseq2/pca_coordinates.csv</code>: DESeq2, edgeR, limma-voom and microarray limma. Only imported results are excluded, because they carry no expression matrix. Columns that name a sample rather than describe its biology are left out of the comparison: the sample identifier, the file paths, the ingest accessions, and the free-text labels <code>sample_title</code>, <code>title</code> and <code>library_name</code>. A label often groups the same way the contrast does, because that is how people write labels, and that resemblance is not evidence of unmodelled structure. A recorded technical factor such as <code>batch</code>, <code>library_prep</code> or <code>sequencing_run</code> is still compared. It compares each sample-sheet column outside the design formula with PC1 and PC2 and reports review-required when that column’s adjusted R&sup2; exceeds the value only 5% of random label assignments reach at the study’s number of samples and groups (0.85 for four samples in two groups, 0.42 for eight, 0.17 for eighteen) and the F-test p-value is below 0.05. Adjusted R&sup2; rises monotonically with the F statistic, so those two conditions are one calibrated test reported twice; the fixed floor of 0.5 it replaces bound only at small sample sizes. A column whose grouping coincides exactly with the contrast factor is reported as aliased with it instead of scored, and each engine screens its own coordinates, so a verdict is engine-relative. The screen is advisory and does not change the design.</p><p>Check 13 and <code>results/deseq2/unchanged_genes.csv</code> are produced on the count-based DESeq2 route only; edgeR, limma-voom, microarray limma and imported results do not write them. Check 13 records completion of a TOST-style calculation; its pass is not an independent proof of equivalence. Check 19 uses configuration names to flag likely orientation mistakes; it cannot know your experimental intent. Checks 02–04 are unused in the published baseline. Read exact rule and route evidence rather than interpreting a check count as a quality score.</p></details><h2 id="troubleshooting">When a check and your expectation disagree</h2><p>Inspect the underlying inputs and report. A batch associated with a PCA axis can be a useful warning, while a real biological grouping can also explain variation. Keep the original run record before deliberately revising the model. See <a href="design.html">design guidance</a>.</p>`},
{slug:'run',title:'Run, stop and resume',group:'Validate and run',summary:'Launch the validated workflow and preserve evidence of what happened.',body:`<p>Before you start, ensure the applicable tools are ready, the final inputs have been checked and the project has enough resources. Keep the computer powered and available during a local run.</p>${step('start','1. Start the validated run','On Run monitor, click Start Run. Follow the phase and progress display. Expand command/raw-log details when you need the exact tool message.',check('The active route should match your intent. A count-matrix run should not appear to download raw reads; imported results should not claim a local model.'))}<h2 id="controls">Execution controls</h2>${table([['Start Run','Executes the configured workflow.','Use after final input validation and resource review.'],['Dry Run','Inspects the workflow graph without performing its computation.','Use before a long run or after changing a route.'],['Stop','Cancels execution through the application.','Use to stop a run safely; do not close a transient Windows terminal window to control it.'],['Resume','Continues an interrupted workflow, reusing eligible completed steps and rerunning incomplete work.','Resolve the original error first and preserve inputs. Changed content must be revalidated.'],['Unlock','Clears a stale workflow lock after an interruption.','Use only after confirming no active run owns the project. A lock is not a signal to start two runs together.']])}${step('interrupted','2. Recover an interruption','Reopen the project and use Resume Interrupted Run when offered. Review logs for the cause before resuming after a failure.',caution('Resume is not a guarantee that all previous steps are reused: changed inputs, workflow versions or incomplete outputs can require work to run again.'))}<p>A run you stop is shown as <strong>Stopped</strong> with a WARNING status, and resuming continues from the completed steps. A failed run is shown as <strong>Failed (exit code N)</strong>, or as <strong>Failed — a rule reported an error</strong> when the launcher returned 0 although a step failed. When the log shows R or Bioconductor packages failing to load, the monitor offers to rebuild the analysis environment from its pinned lock; the command line reports the same failure as exit 5 without that offer. <a href="codes.html#run">Exit codes and statuses</a> lists every failure state.</p><h2 id="finish">3. Review completion and export the record</h2><p>After completion, the status message counts the phase checks that reported a warning or a review-required finding and sends you to Pre-run checks, where the run’s own checks are re-read with their findings. Open <a href="outputs.html">Figures and tables</a> and <a href="checks.html#output-checks">result checks</a>. The After the run actions include Folder, References and Design. Reports → Generate Reports creates summaries; Open Results Report opens the self-contained report.</p>${check('Read warnings and applicable resource failures even when the main computation finished.')+warning('A missing STRING network caused by connectivity is not evidence that no biological associations exist.')}<details><summary>Advanced: command-line interruption</summary><p>The <code>bulkseq run</code> command streams workflow output and exits non-zero on execution failure. Ctrl-C is acted on during a quiet step as well as a talkative one, because the output is drained on a separate reader thread: the process tree is sent TERM, given up to eight seconds to release the working-directory lock, then sent KILL, and the command exits 130. Retain logs and confirm the process has stopped before another run.</p></details>${imageFigure('run-monitor.png','Run monitor','The Run monitor page: Start Run and Dry Run buttons above a collapsed Execution options section, a Workflow status line with an empty progress bar, the After the run buttons Results, MultiQC, Design, References and Folder, and a collapsed Show command and log section.','The Run monitor before a run: Start Run and Dry Run, the workflow status line and progress bar, the After the run actions, and the command and log behind a disclosure. Stop and Resume replace them while a run is active or interrupted.')}`}
);
pages.push(
{slug:'outputs',title:'Read figures, tables and reports',group:'Explore results',summary:'Understand the quantity in each output before interpreting it.',body:`<p>Before you start, confirm the input route, comparison direction and completed checks. A file named deseq2 or a shared results schema does not establish which statistical engine ran.</p>${step('tables','1. Open the result tables','Open Figures and tables and inspect the full differential-expression table before selected gene lists. Read log2FoldChange and adjusted p-values alongside the documented direction. The up/down lists apply both alpha and |log2FC| filters.',warning('Keep missing adjusted p-values distinct from significant or unchanged genes. Non-significance is not an equivalence claim.'))}<h2 id="folders">Where outputs live</h2>${table([['results/counts/','Gene-count matrices and applicable assignment summaries.','Absent for results-only imports; a normalized-expression table is a different quantity.'],['results/deseq2/','Common DE outputs and route-specific normalized-expression/diagnostic tables.','Check recorded engine and input route.'],['results/enrichment/','GO, KEGG, GSEA and configured custom-set outputs.','Read resource status and mapped universe with a result.'],['results/figures/','PNG and SVG figure files.','Retain vector files for resizing and inspect exported labels.'],['results/reports/','Self-contained HTML results report, summaries and provenance exports.','Generate Reports, then Open Results Report.'],['config/, logs/, checks/','Run configuration, execution evidence and validation records.','Preserve these alongside results when archiving a study.']])}<h2 id="figures">2. Read each figure for its intended purpose</h2><p>A volcano combines effect size and adjusted-p evidence. The published baseline uses unshrunken log2 fold change on its x axis. PCA, sample distance and correlation summarize sample structure when an expression matrix exists; they do not independently test the treatment contrast. Heatmap row z-scores show relative within-gene patterns, not absolute expression differences between genes.</p><p>An MA plot combines mean expression and effect size; the required mean must exist. RNA-seq-specific dispersion, Cook’s-distance and library diagnostics do not apply to every route. Imported-results projects cannot supply matrix-based PCA or heatmaps.</p><h2 id="style">3. Change display settings deliberately</h2>${table([['Volcano labels: 15; heatmap genes: 30','Changes how many selected features are displayed.','Illustration: labels 15 → 30 adds annotations, not new DE genes.'],['Volcano y scale: cap / full / sqrt compression','Changes display of very small adjusted p-values. Cap mode marks off-scale values.','Use full height to inspect the tail, or cap to retain readability; none changes the underlying p-values.'],['PCA variable genes: 500','Changes the genes used for the displayed PCA calculation.','This is not merely cosmetic: a different feature subset can change the PCA view.'],['Heatmap z-limit: ±2.5','Clamps the displayed standardized colour scale.','Extreme values share a colour beyond the limit; inspect the table for exact values.'],['Show sample labels','Hides or shows sample text while retaining grouping cues.','Useful for crowded studies; keep an accompanying sample key.'],['Figure size: 6 × 5 inches; PNG 300 DPI','Changes physical export size and raster resolution.','Increase size for a crowded panel; DPI does not increase statistical information.'],['Base font 12; point size 2.5; opacity 0.55','Changes visual readability and overlap.','Enlarge text for a slide; do not interpret a larger point as a larger effect.'],['Enrichment terms: 15','Changes the number of terms shown.','A shortened dotplot is not the complete enrichment table.']])}<p>Use the Style tab, click Regenerate figures, then Refresh figures. Vector (SVG) previews a scalable export. Figure regeneration does not rerun alignment or the primary DE model, although choices such as the PCA feature count change the displayed derived calculation.</p>${step('report','4. Generate and inspect reports','On Reports, click Generate Reports, then Open Results Report. The single-file HTML opens with an index of its sections — recorded settings, study design, figures, which genes changed, functional enrichment, sanity checks, runtime, software and provenance, and a glossary — and carries sortable tables, definitions shown on hover, focus or tap, and a figure viewer with Fit, Actual size and percentage zoom. Sorting and zooming change the display only; the saved tables hold the complete results.',check('Read the Run provenance table under Software &amp; provenance: it names the application and workflow versions that executed, the workflow digest and copy time, the installed environment specification, the environment lock hash and the workflow commit, and states plainly when one of them was not recorded. The identifier-mapping evidence lines the report quotes under enrichment are the same lines <code>results/enrichment/enrichment_summary.txt</code> and the run summary carry, so a mapping exclusion cannot appear in one and be missing from the other. Inspect the exported file before sharing; metadata and sample labels can be sensitive.'))}<details><summary>Advanced: engine parity, ranking and provenance</summary><p>The count engines share one results schema but not one feature set. <code>ncbi_geneid</code>, <code>pca_coordinates.csv</code> with its covariate screen, and the <code>padj_lfc_ge_threshold</code> companion column are written by DESeq2, edgeR and limma-voom alike; the companion column uses each method’s own interval test (DESeq2 <code>greaterAbs</code>, edgeR <code>glmTreat</code>, limma and limma-voom <code>treat</code>) at the configured fold-change threshold, is informational and never decides which genes are called. <code>lfcSE</code> carries a value on DESeq2, limma-voom and microarray limma; edgeR quasi-likelihood reports no per-gene standard error and leaves the column empty. <code>unchanged_genes.csv</code> and check 13 are written on the DESeq2 route only. The recorded fold-change threshold test is named in <code>results/reports/sessionInfo.txt</code>.</p><p>Locally fitted models export a signed model statistic for preranked use, with a documented fallback when no finite statistic is available. Imported results use confirmed log2FoldChange. Tools/references and design exports describe the route that actually ran, including installed environment specification and input provenance rather than attributing inactive defaults to the analysis. The matrix-based Wilcoxon sensitivity check is diagnostic only: when groups are small, exact p-values are discrete and power is limited, so its warning supports rank-concordance review and does not change the differential-expression calls.</p></details>`},
{slug:'enrichment',title:'Enrichment and protein networks',group:'Explore results',summary:'Connect gene-level results to annotations while retaining mapping and service limits.',body:`<p>Before you start, verify the organism, gene identifiers and selected-gene thresholds. Enrichment summarizes annotated sets; it does not demonstrate that a pathway is activated or that an interaction occurred in your samples.</p>${step('enrichment','1. Enable and review enrichment','Enrichment is enabled by default. Direction-split over-representation analyses use selected genes; GSEA uses a ranked list. GO uses an available OrgDb/clusterProfiler route or g:Profiler fallback, and KEGG requires a supported organism code.',check('Inspect mapping coverage, universe and resource status.'),warning('An empty result can mean insufficient evidence, incompatible identifiers, unavailable annotation or failed connectivity.'))}<h2 id="settings">Interpretation settings</h2>${table([['Enrichment on/off','Controls whether enrichment outputs are computed.','Disable when outside the analysis plan or when required services cannot be used.'],['Custom GMT / annotation table','Defines your own gene sets, alongside built-in routes.','Use a curated collection matching the run’s identifiers. A set of symbols cannot directly match unrelated accession IDs.'],['Background gene list','Changes the eligible comparison universe for custom over-representation.','Use a justified tested/eligible background; changing it can change enrichment without changing DE results.'],['GSVA: off','Produces descriptive per-sample scores from supplied custom sets.','Enable with an expression matrix and suitable sets. The heatmap is not a significance test.'],['Genes of interest','Creates focused expression views/count tables where a matrix exists.','Paste IDs that match the run. Low matching coverage must be resolved before interpreting an empty panel.']])}<details><summary>Advanced: ranked lists and annotation limits</summary><p>Built-in over-representation uses tested genes with an adjusted p-value as its universe. Local GSEA ranks by the model’s signed statistic; imported results rank by confirmed effect. KEGG ORA and GSEA are audited separately, so an ORA with few selected genes does not automatically invalidate ranked analysis.</p><p>KEGG keys genes either on bare NCBI GeneIDs or on locus tags, and which form an organism uses decides whether the gene ids must be bridged before the query. The form is taken from the bundled organism catalogue, which records a measured value for every preset KEGG organism; for an organism outside the catalogue the workflow probes KEGG live, falling back through four endpoints, and classifies the keys by majority. The evidence line in <code>enrichment_summary.txt</code> names the form, whether it came from the catalogue or a live probe, and which probe answered; it carries a fraction of numeric keys only where a live probe measured them, so a catalogued organism records <code>probe=not attempted</code> instead. When the form cannot be established and the gene ids are not bare GeneIDs, check 10 reports review-required naming the organism, rather than leaving an empty KEGG table unexplained; the same escalation names the engine or input route when a GeneID-keyed organism is reached from a route that carries no usable <code>ncbi_geneid</code> values. The bridge itself is derived from the annotation’s <code>db_xref</code> field and is written by DESeq2, edgeR and limma-voom; the microarray and imported-results routes have no annotation to derive it from. Do not assume identical annotation coverage across engines or organisms.</p></details><h2 id="network">2. Explore or rebuild the STRING network</h2><p>Open Protein network. Load / refresh network displays the saved run network. Rebuild from STRING contacts STRING and can retrieve a network under a changed confidence threshold. Pointer or keyboard navigation exposes node details; exported GraphML, SIF and cytoscape.js JSON support external editing.</p>${table([['STRING score: 400; range 1–1000','Sets the association-confidence cutoff used to build a network.','A higher cutoff, such as 700, is more stringent and can remove associations; it is not an expression p-value.'],['Seed cap: 400 genes','Limits genes used to seed the network. Selection splits the budget across up/down directions, ranked by adjusted p-value.','Change only with a reason; a capped network is not every significant gene.'],['STRING version: 12.0 baseline','Selects the database version used for associations.','Record realized version and query date when comparing runs.'],['Layout, colour, node size and in-view filters','Changes the displayed saved network.','Re-layout does not alter DE statistics; an in-view edge filter differs from rebuilding the query.']])}<h2 id="connectivity">3. Account for online services and privacy</h2><p>Environment installation and public-read/reference downloads require network access. g:Profiler analysis submits gene identifiers to a remote service. STRING mapping/rebuilding involves remote gene/protein identifier and organism queries or resources; KEGG access retrieves online annotation resources. Review the service and institutional requirements before enabling online interpretation for restricted identifiers.</p><p>Local computation is not a promise of offline operation. STRING is contacted by the documented network route; unavailability yields empty outputs with a warning rather than a biological “no interactions” conclusion. Raw reads are not the input required for these gene-list services, but do not infer a blanket no-network/no-data-transfer guarantee.</p>${check('Record failed or skipped annotation services in the analysis interpretation.')+warning('Downloaded or web-derived associations describe the database’s evidence, not direct measurements of protein interactions in this experiment.')}`},
{slug:'meta-analysis',title:'Combine independent studies',group:'Analysis setup',summary:'Compare the same contrast across studies without treating studies as extra samples.',body:`<p>Before you start, establish that the studies are independent and address the same directionally defined comparison in one organism and compatible gene identifiers. Re-deposited samples are not an independent replication.</p>${step('studies','1. Add study membership','Bring the samples into a project and fill dataset and condition on Samples. Each dataset identifies its study of origin, while condition identifies the compared groups.',caution('A study enters the per-study combination only with at least two replicates in each compared arm, and the combination needs at least two such studies. With fewer it does not run, and check 17 says so; the joint analysis still runs.'),check('Confirm enough studies remain: excluded studies and the reason for each are listed in <code>results/meta/excluded_studies.txt</code>.'))}<h2 id="meta-settings">2. Set the meta-analysis controls</h2>${table([['Multi-study meta-analysis: off','Adds separate study fits and combination alongside the joint analysis.','Enable for independent studies of the same contrast; it is not a way to turn technical repeats into replication.'],['dataset','Separates the per-study fits and supports study adjustment in the joint model.','Illustration: study_A and study_B each include treated and control samples.'],['Per-study enrichment: off','Adds enrichment for each constituent study.','Enable if those separate functional comparisons are required; it adds computation and service use.'],['Meta GO ontology: BP','Selects biological process, molecular function (MF) or cellular component (CC).','Choose the annotation aspect matching your question, not the one yielding the most terms.'],['Meta figure labels 10 / heatmap genes 50 / enrichment terms 6','Limits displayed content in comparative figures.','Changing display counts does not change which genes pass the meta-analysis criteria.']])}<h2 id="method">3. Understand what is combined</h2><p>In the published baseline, each eligible study is fitted separately with DESeq2 using the contrast factor only. The per-study fits do not inherit extra covariates from the joint design. P-values are combined with a replicate-weighted inverse-normal method; unshrunken effects are also combined with an effect-size model. The effect model is fixed-effect for two studies and DerSimonian–Laird random-effect for three or more.</p><p>Direction-discordant genes remain visible but are not called convergent meta-DEGs. The joint analysis adds <code>dataset</code> to any additive design that omits it, the default <code>~ condition</code> or one you typed such as <code>~ batch + condition</code>, provided every term is a sample-sheet column and the result stays full rank. A design with an interaction or nesting operator, or one where adding <code>dataset</code> would be rank-deficient, is left as written and the log says so. A combined p-value is not a guarantee of biological consistency or increased power.</p><p>Cross-study enrichment uses the main enrichment route's identifier policy for official identifiers, the configured keytype and aliases. Exactly one accepted Entrez mapping is used for both the shared universe and every study or convergent foreground. Unresolved one-to-many mappings are excluded rather than selected by database row order. Inspect <code>results/meta/meta_enrichment_mapping.tsv</code> for accepted, unmapped and ambiguous identifiers and check 18 for universe and foreground coverage. An ambiguity finding remains review-required when enrichment later skips for a small set or no terms.</p>${step('review-meta','4. Review the separate report','Inspect meta_analysis_report.html, the tables under results/meta/, constituent-study results and meta-specific checks. Review excluded studies, discordant genes and duplicate-study warnings.',warning('Do not present the joint model and the meta-analysis combination as the same result.'),check('Check that a claimed cross-study finding is supported by the applicable per-study direction and eligibility evidence.'))}<details><summary>Advanced: design and archive limits</summary><p>If the question needs within-study covariate adjustment beyond the documented contrast-only fits, this baseline does not implement that model through the meta switch. The separately versioned validation archive does not establish universal meta-analysis performance. Review <a href="faq.html#version-notices">historical meta-analysis notices</a> before reusing older outputs.</p></details>`}
);
pages.push(
{slug:'cli',title:'Command line and HPC',group:'Reference',summary:'Inspect commands, execute locally and understand cluster preparation.',body:`<p>Before you start, prepare a valid project and an environment containing the workflow tools. The command line exposes project/configuration operations and the same workflow command builder used by the graphical interface.</p>${step('command-help','1. Inspect the installed command','Run bulkseq --help and bulkseq version. From an appropriate source environment, the documented installation is pip install -e ., which installs the graphical interface packages as well; there is no separate command-line-only installation.',check('Use the installed version’s help for exact arguments.'),caution('Installing the command is not the same as installing every analysis backend dependency.'))}<pre><code>bulkseq --help
bulkseq version
bulkseq project create --name study --workdir PATH
bulkseq project info -C PATH
bulkseq config show -C PATH
bulkseq samples show -C PATH</code></pre><h2 id="configuration">2. Inspect and change configuration</h2><p>Configuration keys are validated before a write; an invalid key/value leaves the file unchanged. Use an explicit project path to avoid accidentally editing another project.</p><pre><code>bulkseq config get deseq2.alpha -C PATH
bulkseq config set deseq2.alpha 0.01 -C PATH
bulkseq check -C PATH
bulkseq print-command -C PATH --mode dry-run
bulkseq run -C PATH --mode dry-run</code></pre>${table([['-C / --project PATH','Selects the project; default is current directory.','Use an explicit path in automated work.'],['--json / --quiet','Controls machine-readable output and banner suppression.','Use --json for parsing rather than scraping formatted text.'],['--mode run / dry-run / resume','Selects execution, graph inspection or interrupted-work recovery.','Read the printed command before launching a long run.'],['--exec-profile local / slurm / kubernetes','Selects the execution target.','A profile name does not establish that a cluster is configured or accessible.']])}<h2 id="execute">3. Run and inspect the exit status</h2><pre><code>bulkseq run -C PATH
bulkseq run -C PATH --mode resume</code></pre><p>The command returns 0 on success, 2 for a usage error, 3 for a project or configuration it cannot use, 4 when <code>bulkseq check</code> finds a FAIL, 5 when the workflow fails and 130 when interrupted. Exit 1 means an unexpected error and comes with a traceback. <code>bulkseq --help</code> lists the same codes, and <a href="codes.html#cli">Exit codes and statuses</a> gives each one with what to do next.</p>${warning('<code>bulkseq run</code> does not evaluate the pre-run checks. A script that must not run past a FAIL should call <code>bulkseq check</code> first and stop on exit 4.')+note('A WARNING or REVIEW_REQUIRED finding still lets <code>bulkseq check</code> exit 0, so read the findings as well as the exit code.')}<h2 id="hpc">4. Prepare an HPC target explicitly</h2><p>For Slurm, edit <code>workflow/profiles/site/slurm/config.yaml</code> for your partition, account and walltime. The published profile uses jobs and cores of 16 and a default runtime of 240 minutes, but your site must approve suitable values. Inspect <code>bulkseq print-command --exec-profile slurm</code> before submitting. Compute nodes may lack outbound access; arrange permitted downloads and shared inputs first.</p>${table([['jobs','Limits concurrently submitted work.','Reduce to fit site policy; it is not the number of biological samples.'],['cores','Also affects per-rule thread ceilings in the profile.','Do not reduce below required rule threads without understanding the executor’s effect.'],['runtime / partition / account','Controls scheduler placement and resource request.','Use current site values rather than copying another institution’s partition.'],['Kubernetes image / shared storage','Makes tools and inputs available inside pods.','The published baseline does not supply a proven ready-to-run image; executor selection alone is insufficient.']])}${caution('A cluster dry run parses the graph/profile without proving scheduler submission, container pulling or compute-node execution. The published documentation did not establish real Slurm or Kubernetes execution.')+check('Perform a suitable small execution check under your site’s policy before a full study.')}<details><summary>Advanced: Windows paths and workflow updates</summary><p>Local execution translates supported Windows/WSL paths to WSL2. Ordinary network shares are refused. Cluster profiles are not wrapped in WSL2. <code>bulkseq run</code> synchronizes an outdated copied workflow before a run, as the interface does, so preserve older projects and version records when exact historical reproduction matters. An interrupt is acted on during a quiet step as well, because output is drained on a reader thread: Ctrl-C sends the process tree TERM, allows up to eight seconds for Snakemake to release its lock, then sends KILL, and the command exits 130.</p></details>`},
{slug:'faq',title:'Troubleshooting, versions and citation',group:'Reference',summary:'Resolve common problems and keep software and archive versions distinct.',body:`<h2 id="troubleshooting">Common problems</h2><details open><summary>Setup is slow or a component is not ready</summary><p>Read Show details / log, identify the failed component, resolve that cause and Re-check. The R/Bioconductor environment is a substantial first-run download. A working GUI does not prove the backend is installed; core-only profiles intentionally omit full-only tools.</p></details><details><summary>The run has no PCA or expression heatmap</summary><p>Check the input route. Imported results have no per-sample matrix and cannot produce these outputs. For matrix routes, inspect the applicable rule log and data checks rather than assuming every figure is universal.</p></details><details><summary>There are no significant genes</summary><p>Review the design, contrast, replication, QC and the complete results table. A null result can be scientifically meaningful. Do not change thresholds solely to produce a nonempty list; document any justified exploratory analysis separately.</p></details><details><summary>Enrichment or STRING is empty</summary><p>Inspect annotation availability, identifiers, organism settings and service connectivity. A network warning is not proof that the genes have no interactions. Custom gene sets must use identifiers compatible with the run.</p></details><details><summary>A low-mapping safeguard asks whether to continue</summary><p>Check the intended reference, read source, contamination evidence and relevant logs before continuing. Changing a threshold cannot fix a wrong organism or a mismatched genome/annotation pair.</p></details><details><summary>Numbers use comma decimal separators on my computer</summary><p>Use dot decimals in numeric input and imported tables. The application uses a dot numeric convention. A text value such as 0,05 in a table may be a delimiter problem; inspect the file rather than relying on a spreadsheet display.</p></details><details><summary>How do I update?</summary><p>Use the checksummed official release assets. Close the application before running the Windows installer. Preserve the project and its original version/provenance before rerunning it with an updated workflow. Do not overwrite your only historical results to test an update.</p></details><h2 id="version-notices">Version notices</h2><p>This handbook documents version 0.31.0. The application release and the deposited validation archive are separately versioned. A development checkout does not establish a released platform package.</p><ul><li><strong>Before 0.26.6:</strong> meta-analysis adjusted the wrong reported family before removing direction-discordant genes. Re-run affected meta-analysis outputs; see the <a href="https://github.com/tunabirgun/bulkseq-studio/releases/tag/v0.26.6">0.26.6 release</a>.</li><li><strong>0.29.0:</strong> changes included signed-statistic GSEA ranking, direction-balanced STRING seeds, meta p-value calculation and figure scales/coordinates. Earlier enrichment, network membership and figure ordering can differ; see <a href="https://github.com/tunabirgun/bulkseq-studio/releases/tag/v0.29.0">0.29.0</a>.</li><li><strong>0.30.0:</strong> per-sample strandedness and an organism-specific KEGG GeneID bridge changed relevant outputs. Mixed-library projects and affected KEGG analyses require renewed review; see <a href="https://github.com/tunabirgun/bulkseq-studio/releases/tag/v0.30.0">0.30.0</a>.</li><li><strong>0.30.1:</strong> command-line runs synchronize outdated workflow copies. Record the actual software/workflow used; see <a href="https://github.com/tunabirgun/bulkseq-studio/releases/tag/v0.30.1">0.30.1</a>.</li><li><strong>0.31.0:</strong> several outputs changed. The edgeR and limma-voom routes now carry <code>ncbi_geneid</code>, so KEGG enrichment reaches an organism keyed on NCBI GeneIDs that has no OrgDb instead of returning empty tables; those routes and microarray limma also gain the <code>padj_lfc_ge_threshold</code> companion column, computed with each method&#39;s own interval test (edgeR <code>glmTreat</code>, limma and limma-voom <code>treat</code>), and write <code>pca_coordinates.csv</code>, so the covariate screen (check 23) now runs on every locally fitted engine and can reach a different verdict on each. Check 23 replaces its fixed adjusted-R&sup2; floor of 0.5 with the value only 5% of random label assignments reach at that number of samples and groups. The fixed floor was the stricter of the two from seven samples upward in two groups, so a sample-sheet column that 0.30.1 reported as within chance can now come back review-required. limma-voom now reports <code>lfcSE</code>. Check 23 also stops comparing the sheet&#39;s descriptive label columns, so a study whose sample titles happened to group the way the contrast does can lose a review-required finding it previously reported. Sample sheets may carry an optional <code>library_name</code> column, which is descriptive only and changes no result. Check 08 reports review-required for a DESeq2 interaction design, naming the coefficient actually tested; check 10 escalates when the KEGG key form cannot be measured or a GeneID-keyed organism is reached from a route without usable GeneIDs; a project configuring more than one contrast now states which one was analysed; and the wording of checks 21 and 23 changed. Re-run affected analyses; see <a href="https://github.com/tunabirgun/bulkseq-studio/releases/tag/v0.31.0">0.31.0</a>.</li></ul><p>The deposited 0.26.6 validation archive predates those later output changes and has not established every later output’s equivalence. Treat it as evidence for its recorded scope and version, not a blanket performance guarantee.</p><h2 id="cite">Citation and license</h2><p>BulkSeq Studio is distributed under the MIT License. Cite the exact software version that produced your analysis and its <a href="https://github.com/tunabirgun/bulkseq-studio/releases">release record</a>; include the exported method/tool references applicable to your route. Do not cite the archive version as if it were the installed software version.</p><p>If you use the deposited validation materials, cite the <a href="https://doi.org/10.5281/zenodo.21833538">version 0.26.6 archive</a>. The <a href="https://doi.org/10.5281/zenodo.20955660">concept DOI</a> points to the archive series. Consult the record for its citation metadata and qualifications.</p><h2 id="help">Report a problem</h2><p>Use the <a href="https://github.com/tunabirgun/bulkseq-studio/issues">issue tracker</a> with the application version, platform, input route, operation and sanitized error. Remove private paths, sample/donor identifiers and restricted study content. A minimal synthetic example is preferable to sharing raw research data.</p>`},
{slug:'glossary',title:'Glossary',group:'Reference',summary:`${Object.keys(glossary).length} terms, each linked from the pages that use it. Point at a dotted term anywhere in the handbook to read its definition in place.`,body:Object.entries(glossary).map(([name,definition])=>`<h2 id="${name.toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'')}">${name}</h2><p>${definition}</p>`).join('')}
);
const walkSteps = {
  prepare:{title:'Prepare the environment',purpose:'Make the tools required by your route available.',inputs:'Your operating system and an official release package.',settings:'Choose the platform package and applicable full/core environment. Resource needs depend on the route.',result:'A ready environment and a project folder.',check:'Read every readiness status and resolve Action needed entries before execution.',href:'guide.html'},
  public:{title:'Fetch public metadata',purpose:'Resolve the selected public study into its reads and sample records.',inputs:'SRR / SRP / PRJ accessions or an RNA-seq GSE.',settings:'Use Public accessions and Fetch metadata & build samples. The accession chooses the study; verify inferred layout and groups.',result:'A sample sheet and configured download sources.',check:'Confirm study, biological replicates, layout and condition labels against the source study.',href:'inputs.html#raw-reads'},
  fastq:{title:'Select local FASTQ',purpose:'Connect reads already on disk to the project.',inputs:'FASTQ files, with correctly paired mates for paired-end libraries.',settings:'Select FASTQ Files. One run uses one layout. A mate is the second read of the same sample, not another replicate.',result:'Configured read paths for each sample.',check:'Check file identity, pairing, accessibility and available disk space.',href:'inputs.html#raw-reads'},
  counts:{title:'Import raw counts',purpose:'Start after read processing and counting.',inputs:'A gene-by-sample raw count matrix.',settings:'Use Import count matrix. Estimated counts require the documented opt-in; TPM, FPKM and log-CPM are not raw counts.',result:'A count matrix ready for a local model.',check:'Match sample columns and gene identifiers. A copied-workflow update to the import script or its validator re-imports the matrix. Rounding normalized abundances does not create raw counts.',href:'inputs.html#counts'},
  microarray:{title:'Import microarray intensities',purpose:'Choose processed intensities or supported raw-array processing.',inputs:'A microarray GSE or an already-normalized log2 gene-by-sample table.',settings:'Choose series matrix, supported CEL/RMA or local matrix. Avoid applying log2 twice; 256 becomes 8 after one log2 transform.',result:'An expression matrix for limma.',check:'Confirm platform, normalization, transform decision and numeric dot-decimal columns.',href:'microarray.html'},
  imported:{title:'Import finished statistics',purpose:'Reuse a completed upstream model without fitting a local one.',inputs:'A complete DE results table and its source method/direction.',settings:'Confirm numerator and denominator. Positive log2FC means higher in the numerator; local contrast settings cannot reinterpret it.',result:'An integrity-bound imported table for applicable downstream outputs.',check:'Validate complete rows, unique identifiers, numeric values and source metadata. No counts or PCA are reconstructed.',href:'imported-results.html'},
  samples:{title:'Review sample metadata',purpose:'Connect observations to biological groups and relevant covariates.',inputs:'Sample inventory, conditions and optional batch/donor/dataset columns.',settings:'Save samples.tsv. Use b1/b2 for categorical batches; numeric 1/2 is treated as a continuous covariate.',result:'A saved sample sheet with reviewed identities and groups.',check:'Check independent replication and exact matrix/file-to-sample matching.',href:'project.html'},
  reference:{title:'Match the reference and identifiers',purpose:'Choose the correct organism and annotation context.',inputs:'Organism and, for reads, genome/annotation assembly.',settings:'Use Selected Preset or a compatible custom reference. Imported tables still need matching organism and ID namespace.',result:'Configured reference resources and downstream mappings.',check:'Check assembly compatibility and namespace; a related species is not a substitute.',href:'references.html'},
  processing:{title:'Choose read processing',purpose:'Define how reads become gene-level measurements.',inputs:'Reads and a compatible reference.',settings:'Defaults: fastp trimming, STAR and featureCounts; rRNA/RSeQC/contamination steps are optional. Minimum retained read length is 36: a 30-base read fails.',result:'QC, processed reads and route-specific gene counts; STAR/HISAT2 provide BAMs, Salmon does not.',check:'Changes can alter counts. Check resources and required configs for optional tools.',href:'analysis.html'},
  design:{title:'Define the comparison',purpose:'Specify the biological question and selected-gene criteria.',inputs:'Saved sample groups and a valid model design.',settings:'Default alpha .05 and |log2FC| 1. Illustrative padj .03/log2FC 1.2 passes these but fails alpha .01. treated/control with +1 means a twofold ratio.',result:'A saved contrast, model and calling thresholds.',check:'Review confounding, covariates and direction; adjustment does not repair absent experimental information.',href:'design.html'},
  importThresholds:{title:'Choose downstream thresholds',purpose:'Select gene lists from supplied values without refitting.',inputs:'Validated upstream statistics with confirmed direction.',settings:'Choose alpha and |log2FC|. These change selected genes, not the upstream statistical model or source direction.',result:'A documented downstream selection rule.',check:'Do not invent an upstream adjustment/shrinkage method. Keep unknown information explicitly unknown.',href:'imported-results.html#direction'},
  optional:{title:'Choose interpretation outputs',purpose:'Select enrichment, custom sets and network analysis that fit the study.',inputs:'Compatible identifiers and any custom GMT/background/genes-of-interest lists.',settings:'Enrichment/network are on in the baseline. STRING confidence 400 uses its 1–1000 scale; raising it can reduce edges. GSVA needs a matrix and custom sets.',result:'Configured optional outputs and online-service requirements.',check:'Review universe, organism coverage and connectivity/privacy before queries.',href:'enrichment.html'},
  resources:{title:'Set resources',purpose:'Give the workflow a feasible local budget.',inputs:'Available CPU, RAM and storage; WSL limits on Windows.',settings:'Detect and Recommend, review and Save Resources. More threads do not create memory; do not allocate more than available.',result:'Saved scheduling limits and a runtime estimate.',check:'Leave room for other workloads and reference/intermediate files.',href:'resources.html'},
  check:{title:'Validate and inspect the plan',purpose:'Catch inconsistent inputs before expensive work.',inputs:'The final saved configuration and files.',settings:'Validate current run inputs, then Dry Run. Any changed content invalidates an older pass.',result:'Input checks and a preview of the workflow graph.',check:'Resolve FAIL and review advisories. A dry run is not proof of remote service or scheduler execution.',href:'checks.html'},
  run:{title:'Run and monitor',purpose:'Execute the validated route.',inputs:'Ready environment, final checked inputs and resources.',settings:'Start Run; use Stop for cancellation and Resume after resolving an interruption. Unlock only a stale, inactive project.',result:'Applicable tables, figures, logs and phase checks.',check:'Inspect completion plus warnings. A successful main run does not certify unavailable downstream resources.',href:'run.html'},
  review:{title:'Read and export results',purpose:'Interpret the outputs and preserve their provenance.',inputs:'Completed outputs and route-specific checks.',settings:'Regenerate figures for styling. Labels 15 → 30 adds annotations, not DE genes; PCA feature count can change the displayed PCA calculation.',result:'Reviewed result tables, figures and a self-contained HTML report.',check:'Confirm contrast, model, thresholds, missing outputs, warnings and version before sharing.',href:'outputs.html'}
};
export const walkthroughRoutes = [
  {id:'public',label:'Public accessions',summary:'Start with a public RNA-seq study and follow the read-to-results route.',skipped:'No read-processing stage is skipped; the workflow first retrieves the reads.',steps:['prepare','public','samples','reference','processing','design','optional','resources','check','run','review']},
  {id:'fastq',label:'Local FASTQ',summary:'Start with reads already available on disk.',skipped:'Public read download is skipped. Read QC, processing and quantification still apply.',steps:['prepare','fastq','samples','reference','processing','design','optional','resources','check','run','review']},
  {id:'counts',label:'Raw count matrix',summary:'Fit a local count model from unnormalized gene counts.',skipped:'Download, read QC, trimming, alignment and counting are skipped. No read-level QC is reconstructed.',steps:['prepare','counts','samples','reference','design','optional','resources','check','run','review']},
  {id:'microarray',label:'Microarray',summary:'Analyse normalized intensities through the limma route.',skipped:'RNA-seq read processing and counting do not apply. Array processing and mapping checks replace those stages.',steps:['prepare','microarray','samples','reference','design','optional','resources','check','run','review']},
  {id:'results',label:'Finished DE results',summary:'Interpret an external model with its source direction preserved.',skipped:'Reads, alignment, counting and local model fitting are skipped. Without a sample-expression matrix there is no PCA, count heatmap or normalized-expression export.',steps:['prepare','imported','reference','importThresholds','optional','resources','check','run','review']}
].map(route=>({...route,steps:route.steps.map(key=>walkSteps[key])}));
pages.splice(1,0,{slug:'walkthrough',title:'Walk through your analysis',group:'Start here',summary:'Choose your starting data and follow a connected, route-specific sequence.',body:`<p>Each step explains the action, the settings that change your result, and what to check before moving on.</p><div class="walkthrough"></div><h2 id="full-route">The complete read-to-results route</h2><p>Prepare the environment → add public or local reads → review samples → match the reference → choose processing and design → choose optional outputs → set resources → validate → run → review and export. The diagram is a guide to this sequence; selecting a step does not launch the application or an analysis.</p><details><summary>Read all routes without the interactive diagram</summary>${walkthroughRoutes.map(route=>`<h3 id="route-${route.id}">${route.label}</h3><p>${route.summary} ${route.skipped}</p><ol>${route.steps.map(s=>`<li><a href="${s.href}">${s.title}</a>: ${s.purpose}</li>`).join('')}</ol>`).join('')}</details><h2 id="independent-studies">Combining studies?</h2><p>Finish the common data and design decisions first, then read <a href="meta-analysis.html">multi-study meta-analysis</a>. That optional branch requires independent studies of the same contrast and is not equivalent to pooling every sample without study structure.</p>`});
const patch = (page, from, to) => {
  if (!page.body.includes(from)) throw new Error(`${page.slug}: patch target not found: ${from.slice(0, 70)}`);
  page.body = page.body.replace(from, to);
};
const metaPage = pages.find(page=>page.slug==='meta-analysis');
patch(metaPage, "Cross-study enrichment uses the main enrichment route's identifier policy for official identifiers, the configured keytype and aliases.", "Cross-study enrichment applies the configured per-study FDR and absolute log2-fold-change thresholds before restricting each up/down selection to the shared tested universe. The FDR boundary is strict, the effect boundary is inclusive, and an exact zero effect remains neutral when the effect threshold is zero. It then uses the main enrichment route's identifier policy for official identifiers, the configured keytype and aliases.");
metaPage.body += added('0.32.0','Cross-study enrichment now uses the same FDR and absolute log2-fold-change thresholds as the published per-study up/down tables before applying the shared tested universe and accepted identifier mapping. Exact effect boundaries remain included; zero remains neutral when the threshold is zero. The convergent meta-DEG policy and pooling models are unchanged. Synthetic tests establish exact foreground membership, but no real meta-analysis, enrichment output or published benchmark has been rerun under 0.32.0.');
metaPage.body += added('0.32.0','The separate cross-study report now uses the main report’s native figure viewer. Comparative figures open in a labelled modal with Fit, Actual size and zoom controls; Escape and Close return keyboard focus to the figure that opened it. This changes report viewing only: no meta-analysis figure, table or result is recalculated.');
const outputsPage = pages.find(page=>page.slug==='outputs');
outputsPage.body += added('0.32.0','Sortable report columns retain table headers for assistive technology. Select the labelled header button with a mouse, Enter or Space to cycle ascending, descending and the source order. Sorting changes only this report view. Machine, full-configuration and imported-results provenance tables expose their left cells as row headers.');
const guidePage = pages.find(page=>page.slug==='guide');
guidePage.body += added('0.32.0','Installed-environment provenance records lock only when setup used the exact linux-64 lock file. A floating-spec install records fallback with the actual specification filename and SHA-256, including a direct native Linux ARM install. Core installs remain core. The published AppImage remains x86-64; this provenance correction does not establish an ARM package or end-to-end ARM run.');
const designPage = pages.find(page=>page.slug==='design');
designPage.body += `${added('0.32.0','edgeR, limma-voom and microarray limma now form the configured numerator-minus-denominator comparison by factor position. Distinct condition levels containing spaces, hyphens or dots remain distinct even when they share an R-safe spelling, such as A-B and A.B. Internal model names prevent a sample-sheet column named grp from changing the contrast factor and keep group and covariate coefficients unique. The fitted model remains the documented additive group-means design; these engines still reject interactions. Fixed-seed synthetic fits agree with an independent clean-label numeric-contrast construction, but no real study or published benchmark has been rerun under 0.32.0.')}<h2 id="try-thresholds">Try an illustrative threshold</h2><p>This example is synthetic and changes no project. Both adjusted-p and effect-size criteria must be satisfied.</p><div class="threshold-example"></div>`;
const projectPage = pages.find(page=>page.slug==='project');
patch(projectPage, 'On Project, choose a new local project folder. The application writes configuration under config/, copies its workflow and records a provenance manifest. On Windows, Use WSL filesystem places the project on the Linux filesystem; ordinary network shares are refused.', 'On Project, choose a new local project folder. The application writes configuration under config/, copies its workflow and records a provenance manifest. The name must identify an immediate child of the selected working directory: `.` and `..`, and links that resolve outside it, are refused. An existing non-empty directory requires confirmation before it is scaffolded; an existing file is refused. On Windows, Use WSL filesystem places the project on the Linux filesystem; ordinary network shares are refused.');
const cliPage = pages.find(page=>page.slug==='cli');
patch(cliPage, 'Local execution translates supported Windows/WSL paths to WSL2. Ordinary network shares are refused. Cluster profiles are not wrapped in WSL2. <code>bulkseq run</code> synchronizes an outdated copied workflow before a run, as the interface does, so preserve older projects and version records when exact historical reproduction matters.', 'Local execution translates supported Windows/WSL paths to WSL2. Ordinary network shares are refused. Cluster profiles are not wrapped in WSL2. <code>bulkseq run</code> and the interface synchronize an outdated copied workflow by staging and verifying a complete copy. If a recorded digest disagrees with the project workflow, the run stops without overwriting files; review the edits or restore the recorded workflow. A copy without a valid digest is repaired only when its actual tree matches the bundled workflow; otherwise it stops for review. A valid legacy recorded workflow is upgraded with the original tree retained in a project-local backup. The run report records the execution-tree digest separately from the bundled-workflow identity.');
patch(cliPage, '<h2 id="execute">3. Run and inspect the exit status</h2>', '<h2 id="sample-sheet-path">Configured sample sheet</h2><p><code>bulkseq project info</code>, <code>bulkseq samples show</code>, and <code>bulkseq check</code> read <code>input.samples</code>. Set that field to a path relative to the project or to an absolute path; the conventional <code>config/samples.tsv</code> is used only when it remains the configured value. <code>samples show</code> and <code>check</code> name a missing or malformed configured sheet; <code>project info</code> retains its zero-sample summary for an unreadable sheet.</p><p>On the local FASTQ route, <code>check</code> requires each named read file. Relative FASTQ cells are resolved against the selected project, so <code>bulkseq check -C PATH</code> works from another directory without changing the sheet. Pending reads are accepted only for SRA, count-matrix, microarray, and imported-results routes, which do not require local FASTQ inputs.</p><h2 id="execute">3. Run and inspect the exit status</h2>');
const microarrayPage = pages.find(page=>page.slug==='microarray');
patch(microarrayPage, '<h2 id="result">4. Run and review array-specific checks</h2>', `${added('0.32.0','GEO annotation is parsed across every candidate and repeated row for each probe. A probe enters MaxMean collapse when the combined known candidates identify exactly one distinct gene; ambiguous, unknown and missing-annotation probes are excluded and counted by check 12. The probe-map table retains escaped raw annotation, sorted candidates and the resolution class. Local gene-level matrices keep their supplied identifiers. Synthetic tests establish this mapping contract; no GEO study or published microarray benchmark has been rerun under 0.32.0.')}<h2 id="result">4. Run and review array-specific checks</h2>`);
const enrichmentPage = pages.find(page=>page.slug==='enrichment');
patch(enrichmentPage, '<details><summary>Advanced: ranked lists and annotation limits</summary>', `${added('0.32.0','GSEA eligibility is separate from the ORA tested family. A row with a missing adjusted p-value enters the ranked population only when its route-specific rank and raw p-value are finite. An additional adjusted-p-missing row without finite raw-p evidence, including a DESeq2 Cook’s-distance outlier, remains excluded; legacy adjusted-p-finite rows retain their supported eligibility. Built-in routes keep their established signed-statistic choice and fallback; custom GSEA remains ranked by log2 fold change. Fallback KEGG routes reduce source aliases once in the final GeneID space, which can change already-ranked alias groups as well as admit newly eligible rows. Synthetic offline tests establish this contract, but no real enrichment analysis or published benchmark has been rerun under 0.32.0.')}<details><summary>Advanced: ranked lists and annotation limits</summary>`);
patch(enrichmentPage, 'Built-in over-representation uses tested genes with an adjusted p-value as its universe. Local GSEA ranks by the model’s signed statistic; imported results rank by confirmed effect.', 'Built-in over-representation uses tested genes with an adjusted p-value as its universe. That universe and its selected foregrounds do not expand when an independently filtered row is added to GSEA. Local GSEA ranks by the model’s signed statistic; imported results rank by confirmed effect. A table without raw-p evidence retains the legacy adjusted-p eligibility because the workflow cannot infer why an adjusted value is missing. On fallback KEGG routes, every eligible source score is reduced once after its final GeneID is known; multiple source aliases can therefore change an existing canonical rank even when no adjusted-p-missing row is added.');
const faqPage = pages.find(page=>page.slug==='faq');
patch(faqPage, 'This handbook documents version 0.31.0. The application release and the deposited validation archive are separately versioned. A development checkout does not establish a released platform package.', `This handbook documents version ${documentedVersion}, the current public release. The deposited validation archive remains separately versioned as 0.26.6.`);
patch(faqPage, '<ul><li><strong>Before 0.26.6:</strong>', '<ul><li><strong>0.32.1:</strong> documentation, command-line and interface-text corrections; analysis outputs are unchanged from 0.32.0, and the bundled pasilla benchmark rerun under 0.32.1 reproduced its recorded result exactly. A <code>config/config.yaml</code> that cannot be read or does not validate now makes <code>bulkseq</code> exit 3 instead of failing with exit 1, and <code>bulkseq check</code> reports the most severe finding as its overall status whatever the order of the findings. See the <a href="https://github.com/tunabirgun/bulkseq-studio/releases/tag/v0.32.1">0.32.1 release notes</a>.</li><li><strong>0.32.0:</strong> Count-matrix imports reject malformed, negative and undeclared fractional cells before conversion, and microarray probes assigned to multiple distinct genes are excluded before MaxMean collapse. Explicitly admitted RSEM/tximport estimates retain the documented rounding route. Microarray mapping evidence retains every candidate and reports ambiguous, unknown and missing-annotation exclusions. Synthetic regressions establish these contracts; the historical count and GEO microarray benchmark claims have not been reproduced under 0.32.0.</li><li><strong>Before 0.26.6:</strong>');
patch(faqPage, 'before MaxMean collapse. Explicitly admitted', 'before MaxMean collapse. GSEA admits an additional missing-adjusted-p row only with a finite route-specific rank and finite raw p-value, while leaving the ORA family unchanged; legacy adjusted-p-finite rows retain their supported eligibility. Fallback KEGG rankings reduce source aliases once in final GeneID space, so an already-ranked alias group can change. Explicitly admitted');
patch(faqPage, 'Fallback KEGG rankings reduce source aliases once in final GeneID space, so an already-ranked alias group can change. Explicitly admitted', 'Fallback KEGG rankings reduce source aliases once in final GeneID space, so an already-ranked alias group can change. edgeR, limma-voom and microarray limma now use positional numeric contrasts, preserving distinct condition labels that share an R-safe spelling and preventing a metadata grp column from shadowing the configured contrast factor. Explicitly admitted');
patch(faqPage, 'preventing a metadata grp column from shadowing the configured contrast factor. Explicitly admitted', 'preventing a metadata grp column from shadowing the configured contrast factor. Cross-study enrichment applies the configured per-study FDR and absolute log2-fold-change thresholds before the shared-universe and accepted-mapping restrictions; exact zero remains neutral at a zero effect threshold. Explicitly admitted');
patch(faqPage, 'historical count and GEO microarray benchmark claims have not been reproduced under 0.32.0.', 'historical count, GEO microarray, enrichment and meta-analysis benchmark claims have not been reproduced under 0.32.0.');
patch(faqPage, 'historical count, GEO microarray, enrichment and meta-analysis benchmark claims have not been reproduced under 0.32.0.', 'historical count, GEO microarray, enrichment and meta-analysis benchmark claims have not been reproduced under 0.32.0. See the <a href="https://github.com/tunabirgun/bulkseq-studio/releases/tag/v0.32.0">0.32.0 release notes</a>. The 0.32.0 interface update gives critical accession, design, output, figure-preview and PPI edge-filter controls specific Qt accessible names and descriptions, associates composite labels with their fields, and restores Tab navigation from the multiline accession editor. The current-view edge filter maps slider values 0–100 to displayed confidence 0.00–1.00 without rebuilding the network. Focused tests query the Qt accessibility interface and keyboard focus; no native screen-reader session has been performed.');
// Version notices read newest first; "Before 0.26.6" is the oldest entry.
{
  const faq = pages.find(page => page.slug === 'faq');
  const block = /(<h2 id="version-notices">[\s\S]*?<ul>)([\s\S]*?)(<\/ul>)/;
  if (!block.test(faq.body)) throw new Error('faq: version-notices list not found');
  faq.body = faq.body.replace(block, (_, head, items, tail) => {
    const key = li => {
      const m = li.match(/<strong>(Before )?(\d+)\.(\d+)\.(\d+):/);
      if (!m) throw new Error(`faq: version notice without a version: ${li.slice(0, 60)}`);
      return [+m[2], +m[3], +m[4] - (m[1] ? 0.5 : 0)];
    };
    const list = items.match(/<li>[\s\S]*?<\/li>/g);
    list.sort((a, b) => { const x = key(a), y = key(b); return y[0] - x[0] || y[1] - x[1] || y[2] - x[2]; });
    return head + list.join('') + tail;
  });
}
const vocabulary = {
  guide:['WSL2'],inputs:['FASTQ','Count matrix'],project:['Biological replicate','Covariate'],references:['Gene identifier'],design:['Contrast','Adjusted p-value','log2 fold change'],outputs:['PCA','Provenance'],enrichment:['Enrichment','Universe','GSEA','GSVA'],analysis:['Strandedness']
};
for (const [slug,terms] of Object.entries(vocabulary)) {
  const page=pages.find(page=>page.slug===slug);
  page.body += `<p class="glossary-links">Terms on this page: ${terms.map(term).join(' · ')}.</p>`;
}

// ---------------------------------------------------------------------------
// Tutorial and explanation pages, then the Diátaxis layout the build navigates by.
// ---------------------------------------------------------------------------
const card = (kind, href, title, text) => `<a class="quadrant" href="${href}"><span class="quadrant-kind">${kind}</span><strong>${title}</strong><span>${text}</span></a>`;

pages.push({slug:'tutorial',title:'Your first analysis',group:'Tutorial',summary:'Run a bundled four-sample study from beginning to end, and compare your result with a known answer.',body:`<p>This tutorial runs one complete analysis. It asks you to make no choices: the study, the reference, the comparison and the settings all come from a dataset bundled with the application, and the result it produces has a recorded value you can check your own against. Work through it once before reading anything else, then use the <a href="walkthrough.html">walkthrough</a> when you bring your own data.</p><h2 id="what-you-will-run">What you will run</h2><p>The bundled study is a four-sample paired-end subset of the pasilla RNAi experiment in <em>Drosophila melanogaster</em> (GEO series GSE18508), with two untreated samples and two in which CG8144 was knocked down by RNAi. One sequencing run is used for each biological sample, which keeps the download to about 1.6 GB of compressed reads and 23.6 million read pairs in total.</p><p>Reads are aligned with STAR against Ensembl release 111 of the BDGP6.46 assembly, counted with featureCounts, and tested with DESeq2 using the additive design <code>~ condition</code> with <code>untreated</code> as the reference level.</p>${note('Nothing here is simulated. The workflow downloads the published reads, builds a genome index and fits the model, exactly as it would for your own study. Expect it to occupy a laptop for a while; the interface can estimate the time from your own machine before you start.','This is a real analysis')}<h2 id="before-you-start">Before you start</h2><p>Install the application and complete the environment setup described in <a href="guide.html">Install and first run</a>, and run <strong>Check Environment</strong> until it reports the analysis stack as ready. The tutorial needs a working internet connection, because it downloads both the reads and the reference, and free space in the working directory well beyond the 1.6 GB download, because the genome index, the trimmed reads and the alignments are written there too; the application warns when less than 5 GB is free but does not stop you, so treat 5 GB as a floor rather than a budget for this run.</p>${check('Check Environment reports the tools and the R stack as available.')+caution('If it does not, resolve that first: every later step depends on it, and a failure here will surface much later as a rule that cannot start.')}<h2 id="create">Step 1. Create the project</h2><p>Open the <strong>Project and data</strong> stage. Choose a working directory with enough free space, give the project a name, then press <strong>Create Benchmark Project</strong> and select <em>Pasilla paired-end subset</em> from the list.</p><p>The application scaffolds a complete project rather than an empty one. It writes the sample sheet, the list of sequencing accessions and a manifest recording which bundled dataset the project came from, and it fills in the configuration: the SRA input route, the paired layout, the Ensembl reference preset, STAR with featureCounts, and the comparison.</p>${imageFigure('four-stage-navigator.png','The four-stage navigator','The application window in light mode: the four stage groups listed down the left with Project and data selected, the Project page open with its project-location fields, and the New Project, Open Existing Project, Create Benchmark Project and Check Environment buttons below them.','The four-stage navigator groups the twelve pages into Project and data, Analysis setup, Validate and run, and Explore results. The selected stage is outlined on the left and its own pages run across the top. The status bar carries the running version at the right.')}<h2 id="read-what-was-created">Step 2. Read what was created</h2><p>Open the sample sheet on the Samples page of the same stage. Four rows are listed, two for each condition:</p><table><thead><tr><th>Sample</th><th>Condition</th><th>Run accession</th></tr></thead><tbody><tr><td>untreated_3</td><td>untreated</td><td>SRR031714</td></tr><tr><td>untreated_4</td><td>untreated</td><td>SRR031716</td></tr><tr><td>cg8144_rnai_3</td><td>cg8144_rnai</td><td>SRR031724</td></tr><tr><td>cg8144_rnai_4</td><td>cg8144_rnai</td><td>SRR031726</td></tr></tbody></table><p>This is the smallest design that supports a differential-expression test: two biological replicates on each side of one comparison. Two replicates per group is a lower bound rather than a recommendation, and this dataset is used here because it is small and its answer is known, not because the design is generous.</p>${check('Four rows, two conditions, and a run accession on every row.')+caution('If the table is empty, the project was not scaffolded from the bundled dataset; create it again with Create Benchmark Project rather than editing the sheet by hand.')}<h2 id="confirm-the-comparison">Step 3. Confirm the comparison</h2><p>Open <strong>Analysis setup</strong> and look at the design and contrast. The design formula reads <code>~ condition</code>, the reference level is <code>untreated</code>, and the contrast compares <code>cg8144_rnai</code> against <code>untreated</code>. A positive log2 fold change therefore means higher expression under RNAi.</p><p>Change nothing. Every default here was set by the bundled dataset, and the recorded result in step 6 assumes them. <a href="design.html">Design, contrast and thresholds</a> explains what each of these controls once you are working with your own study.</p><h2 id="run-the-checks">Step 4. Run the pre-run checks</h2><p>Open <strong>Validate and run</strong> and start the pre-run checks. They read the configuration, the sample sheet and the declared inputs, and report on the design, the identifiers, the reference and the route. Because the reads have not been downloaded yet, the checks accept pending files on this route rather than failing on their absence.</p><p>Read the output rather than only the verdict. <a href="checks.html">Pre-run and result checks</a> describes what each check tests and how to act on a warning.</p>${check('No check reports a failure. A warning is informative and does not stop the run; a failure means the run would be invalid and must be resolved first.')+note('On this dataset the overall status is WARNING: check 01 reports that <code>untreated</code> and <code>cg8144_rnai</code> each have fewer than the recommended three biological replicates. That is the two-versus-two design from step 2, so continue to the run.','Expected on this dataset')}<h2 id="start-the-run">Step 5. Start the run</h2><p>Start the run and leave it. The workflow downloads the reads, fetches and indexes the reference, aligns, counts, fits the model and produces the figures and the report. The monitor names the step in progress in plain language and shows the percentage of steps completed and the elapsed time; the log records what each step did.</p><p>The run can be stopped and resumed. Resuming revalidates the inputs instead of trusting the earlier pass, so a file you replaced while the run was stopped is detected rather than inherited. <a href="run.html">Run, stop and resume</a> covers this in full.</p><h2 id="check-the-result">Step 6. Check your result</h2><p>When the run finishes, open <strong>Explore results</strong>. The differential-expression table is <code>results/deseq2/deseq2_results.csv</code>. On this dataset, with these settings, it holds 7,532 tested genes, of which 467 have an adjusted p-value below 0.05. That figure was re-measured under release 0.32.1 from the installed Windows package, where the count matrix and the results table matched the 0.31.0 result byte for byte. Read it as the reference point for this dataset rather than a guarantee for a later release; the changelog entry for your version states which benchmark claims it re-measured.</p><p>Treat a close match as success. An equal count means you reproduced the recorded baseline exactly; a count in the same region indicates the analysis ran correctly with some difference in tool versions or settings; a count of zero, or one in the thousands, means something went wrong earlier and the log is where to look.</p>${check('Combined over-representation returns no GO biological-process terms on this four-sample subset. The dot plot falls back to the up-regulated terms and captions which set it is showing, so it is not empty, but it rests on one direction only. Read <code>results/enrichment/enrichment_summary.txt</code> for the combined, up-regulated and down-regulated counts before drawing anything from it. A small study with few selected genes often has little or no enrichment to report, which is a finding about the data rather than a failure of the analysis.','A thin enrichment result is the expected outcome here')}<h2 id="what-next">What to read next</h2><p>You have now seen the whole path once. To bring your own data in, start from <a href="inputs.html">Choose an input route</a>, which identifies which of the five entry points matches what you actually have, and keep the <a href="walkthrough.html">walkthrough</a> open beside the application. To understand what the numbers you just produced mean, read <a href="interpreting.html">What the numbers mean</a>.</p>`});

pages.push({slug:'safeguards',title:'What the workflow checks for you',group:'Explanation',summary:'The verification the application performs on your behalf, and the judgements it deliberately leaves to you.',body:`<p>A pipeline can complete without producing a defensible result. The safeguards described here exist because the failures that matter in expression analysis are quiet ones: an input replaced between two runs, a library orientation assumed rather than measured, a probe standing for two genes. Each is checked because it can be checked mechanically. What remains is the part that cannot be, and that part is yours.</p><h2 id="completion-is-not-validity">Completion is not validity</h2><p>A successful run means the computation finished. It does not mean the design was adequate, the samples were comparable, the contrast answered your question, or the result is biologically meaningful. The application is built so that the record of what it did survives the run and can be examined afterwards; it is not built to certify the study.</p><h2 id="validation-is-revalidated">Validation is revalidated</h2><p>Pre-run checks store content fingerprints for the configuration, the sample sheet, the local inputs, the reference locks and the index files. Starting or resuming revalidates them. The reason is specific: a validation result that is remembered rather than recomputed will happily certify a file that has since been replaced, and the analyst has no way to see that from the output. An edited input cannot inherit an earlier pass.</p><h2 id="strandedness-per-sample">Strandedness is decided per sample</h2><p>Each sample's library type is inferred from its own data and applied with its own counting orientation. A project that mixes library types is named as such rather than forced onto one code. Guessing a single orientation for a heterogeneous set of libraries produces counts that look ordinary and are wrong for a subset of the samples, which is exactly the kind of error that survives review.</p><h2 id="unmodelled-structure">Unmodelled structure is screened, not corrected</h2><p>For every sample-sheet column outside the design formula that varies between samples without being unique to each one, the workflow tests that column against the run's principal components and reports the result. A column holding one value throughout, or a different value in every row, carries no structure the test could detect and is skipped without a verdict of its own. This is a warning system, not an adjustment: nothing is added to your model automatically. Two engines can reach different verdicts on the same samples, because each screens its own coordinates, so the screen tells you where to look rather than what to conclude.</p><p>Descriptive columns are excluded from the screen. A library name or a sample title labels a sample; testing it against the principal components asks a question with no answer, and reporting the result would invite a reader to act on noise.</p><h2 id="imported-results">Imported results are not relabelled</h2><p>A differential-expression table you supply is validated in full, bound to its hash and schema, and reported as what it is. The report never claims a model the application did not fit. The alternative — presenting an imported table under the application's own method description — would make an analysis look reproducible by this workflow when it is not.</p><h2 id="counts-validated">Count matrices are validated before conversion</h2><p>Missing, nonnumeric, nonfinite and negative cells are refused before anything is written. A non-integer value requires you to declare explicitly that the matrix holds RSEM or tximport estimated counts, and is then rounded by a stated rule. When at least half the sample columns have totals within one per cent of a million, a warning says the data may be normalized; that warning does not by itself reclassify valid integer counts as TPM. The distinction matters because count models assume counts, and a normalized matrix passed to one produces confident nonsense.</p><h2 id="probes">Ambiguous microarray probes are excluded</h2><p>Platform annotation is parsed across every listed candidate and every row for a probe. Only probes resolving to exactly one gene enter the collapse step. Ambiguous, unknown and missing mappings are retained in the probe-map evidence and counted, rather than silently assigned to whichever gene happens to be listed first.</p><p>This applies to the route that has platform annotation to parse. A gene-level matrix you supply yourself carries no probe-to-gene table, so its row identifiers are taken as gene identifiers directly and no ambiguity screening happens at all. The identifiers you supply are the identifiers the analysis uses.</p><h2 id="what-is-not-checked">What none of this checks</h2><p>No safeguard here evaluates whether your replicates are biological or technical, whether the contrast you configured is the comparison your question needs, whether a batch you did not record is driving the result, or whether the effect you found is large enough to matter. Those judgements are not mechanical, and presenting them as passed checks would be worse than leaving them open. Read <a href="checks.html">Pre-run and result checks</a> for what is tested, and <a href="interpreting.html">What the numbers mean</a> for how far a result reaches.</p>`});

pages.push({slug:'engines',title:'Choosing a differential-expression engine',group:'Explanation',summary:'Why DESeq2 is the default, when another engine is a better fit, and what changes when you switch.',body:`<p>Four differential-expression engines are available: DESeq2, edgeR quasi-likelihood and limma-voom for count data, and limma for microarray intensities. They are not interchangeable spellings of one method. Each makes different assumptions about how variance behaves, and on a given dataset they will agree about the strong effects and disagree at the margin.</p><h2 id="in-common">What they have in common</h2><p>All four fit the design you configure and write the same results schema, so the downstream figures, tables, enrichment and reports do not change shape when you change engine. They do not all get there the same way. DESeq2 receives your formula directly and names its contrast by level. The three alternatives are fitted through a group-means matrix and form the numerator-minus-denominator comparison by factor position, which is what keeps condition levels that differ only in spacing or punctuation distinct and stops a sample-sheet column from displacing the contrast factor you configured.</p><p>The shared schema has documented gaps rather than identical contents. Microarray limma assigns no NCBI GeneID and no biotype; edgeR quasi-likelihood reports no per-gene standard error for the log fold change, so that column is empty rather than different; and the equivalence test is produced on the DESeq2 route only.</p><h2 id="deseq2">DESeq2, the default</h2><p>DESeq2 is the default because it behaves well on the designs this application is most often used for: few replicates per group, count data, and a single contrast of interest. It estimates dispersion by pooling information across genes, which is what makes a two-versus-two comparison tractable at all, and it applies independent filtering and outlier handling by rules that are documented and reproducible.</p><h2 id="edger">edgeR quasi-likelihood</h2><p>The quasi-likelihood F-test is designed to account for the uncertainty in each gene's dispersion estimate, and the edgeR literature reports error-rate control closer to nominal than a likelihood-ratio test at small sample sizes. That is a property of the method, not a prediction about your gene list: which engine returns more genes on a given dataset depends on the dispersion structure, the effect sizes and the depth, and nothing in this application measures that comparison for you. If your concern is that a list is too permissive, running edgeR as a second engine is more informative than tightening a threshold, because the two methods disagree for reasons you can inspect rather than by construction.</p><h2 id="voom">limma-voom</h2><p>limma-voom transforms counts and models the mean-variance relationship with observation weights, then uses the linear-model machinery that limma has long applied to arrays. It scales well to larger sample numbers, and a reviewer used to array analysis may ask for it. On very small designs it has less to work with than the count models: the mean-variance trend it fits pools information across all genes, but each gene still has few residual degrees of freedom, so the resulting weights rest on a thin per-gene base.</p><h2 id="microarray-limma">limma for microarrays</h2><p>Microarray intensities are not counts, and no count model applies to them. limma is not an alternative here but the method for the route. The comparison it forms follows the same factor-position rule as the count engines, so a contrast means the same thing across routes even though the underlying model does not.</p><h2 id="what-switching-changes">What switching changes</h2><p>Changing the engine is a change of analysis, not of presentation. The gene list, the effect sizes, the standard errors and every downstream output derived from them will differ. If you report results from one engine, report which one; a figure regenerated after an engine change is a different result, not a restyled one.</p>${warning('Agreement between engines is reassuring and disagreement is informative, but choosing the engine that produced the longer list after seeing both is selection on the outcome. Decide which engine answers your question before you look, and report the others as the sensitivity analysis they are.','Running more than one engine')}<h2 id="limits">What the alternative engines will not do</h2><p>edgeR, limma-voom and microarray limma fit the documented additive group-means design only. Interaction and nesting operators are rejected by them rather than silently reinterpreted, because a formula that is accepted and then fitted as something simpler is the worst available outcome. DESeq2 is the exception: it accepts a typed interaction design, subject to the contrast-extraction caveat described on <a href="design.html">Design, contrast and thresholds</a>. If your question requires an interaction term, that is a design question to resolve before choosing an engine. Practical settings for all of this are on <a href="design.html">Design, contrast and thresholds</a>.</p>`});

pages.push({slug:'interpreting',title:'What the numbers mean',group:'Explanation',summary:'How far an adjusted p-value, a fold change and an enrichment result actually reach.',body:`<p>The outputs of this workflow are easy to read and easy to over-read. This page is about the second problem. It describes what each quantity establishes, and the claims that do not follow from it.</p><h2 id="adjusted-p">An adjusted p-value is a selection rule</h2><p>An adjusted p-value controls the expected proportion of false positives among the genes you select. It is a property of the list, not of any gene in it. A gene with an adjusted p-value of 0.04 is not ninety-six per cent likely to be truly changed; it is a member of a set constructed so that, on average, a stated fraction of its members are not. Moving the threshold mostly changes the list rather than the evidence, with one caveat specific to the default engine: DESeq2's independent filtering is tuned to the alpha you set, so changing it moves which weakly expressed genes are filtered out and the adjusted p-values shift with them.</p><h2 id="not-significant">Not significant is not evidence of no change</h2><p>A gene that fails the threshold may be unchanged, or may be changed by an amount this experiment could not resolve. The two are not distinguishable from a p-value above a cut-off. If the absence of an effect is your claim, an equivalence test asks that question directly; a non-significant result does not answer it, however many genes share the outcome.</p><h2 id="fold-change">Fold change, shrunken and raw</h2><p>A log2 fold change on a base-two scale is an effect size: one unit is a doubling. Shrinkage moves the estimates of poorly measured genes towards zero, which makes ranking and plotting more stable but changes the numbers. This workflow computes shrunken estimates and records them, but it applies the fold-change threshold to the unshrunken value, so the gene list is selected on the raw estimate. Raw and shrunken estimates answer slightly different questions, so a figure and a table that disagree may simply be reporting different ones. Check which you are looking at before reconciling them.</p><h2 id="enrichment">Enrichment answers a narrower question than it appears to</h2><p>Over-representation asks whether your selected genes contain more members of a gene set than a background would give. That background — the tested universe — determines the answer as much as the selection does, and genes excluded from the universe cannot contribute to any term. Ranked enrichment asks a different question again, using the whole ranked list rather than a selection. Neither establishes that a pathway is active, that it is causal, or that it is regulated; both establish that annotated membership is distributed unevenly with respect to your statistic.</p><h2 id="empty-enrichment">An empty result can be the correct result</h2><p>A small study with few selected genes often has no enrichment to report. An empty dot plot in that situation is an accurate summary, not a broken figure, and the enrichment summary file records why nothing was drawn. Reading it before assuming a fault will save more time than rerunning the step.</p><h2 id="networks">A protein-interaction network is a hypothesis</h2><p>Network edges are database assertions of varying provenance and confidence, assembled from experiments that were not your experiment. A dense cluster among your selected genes is a reason to look more closely at those genes; it is not independent confirmation of your result, because the network did not observe your samples. The confidence filter changes what is drawn, not what is known.</p><h2 id="what-to-report">What to report</h2><p>Report the engine, the thresholds, the contrast and its direction, the number of genes tested rather than only the number selected, and the software version that produced the numbers. Each changes what a reader can conclude. The settings are kept with the run in its configuration and parameter records, described on <a href="outputs.html">Read figures, tables and reports</a>; the versions and environment are covered on <a href="provenance.html">Reproducibility and provenance</a>. The output files themselves are described on <a href="outputs.html">Read figures, tables and reports</a> and <a href="enrichment.html">Enrichment and protein networks</a>.</p>`});

pages.push({slug:'provenance',title:'Reproducibility and provenance',group:'Explanation',summary:'What a finished run records, and what a changed scientific output means for an analysis you have already reported.',body:`<p>Reproducibility here means something narrow and checkable: that the record a run leaves behind is sufficient to say what was computed, with which software, from which inputs. That record is written whether or not anyone reads it, which is the point — its value appears months later, when the question arrives and the run is long finished.</p><h2 id="what-is-recorded">What a run records</h2><p>The run summary names the application and workflow versions that actually executed, which are not necessarily the versions bundled with the application you launched. It records the execution-tree digest separately from the bundled-workflow identity, the installed environment specification, and the tools and reference files belonging to the route that ran. Any setting that differs from the bundled default is recorded with both its default and the value used, so a customization is never left implicit. A control set by hand to the value it already had is indistinguishable from one never touched, because the two produce the same configuration.</p><p>Workflow synchronization stops if a recorded project copy has local edits, rather than overwriting them. An edited workflow is a legitimate thing to have; an edited workflow silently replaced mid-study is not.</p><h2 id="two-versions">Two versions, two jobs</h2><p>The application version and the workflow version answer different questions. The application version identifies the interface you used. The workflow version governs whether an existing project re-copies the bundled workflow, but it is not the only trigger: a project also re-syncs when the bundled workflow's file content has changed since its last copy, so a same-version revision of the analysis code still reaches projects that already exist. When you compare two runs, the versions in their summaries are the ones that matter, not the version of the application currently installed.</p><h2 id="results-move">Why results can move between releases</h2><p>Some releases change a scientific output: a mapping rule, a selection boundary, a ranking input. When that happens the change is marked in the changelog with a re-run notice, and the site's <a href="faq.html#version-notices">version notices</a> list which release changed which output. This is deliberate. A silent correction would leave two incompatible sets of numbers circulating with no way to tell them apart.</p><p>If you have reported results from an earlier release, a notice affecting your route does not invalidate what you reported. It tells you that a rerun today may not reproduce it, and which part of the analysis is responsible. Whether to rerun is a judgement about your claim, not a requirement imposed by the software.</p><h2 id="citing">Cite the version that produced your numbers</h2><p>Cite the exact application version recorded in your run summary, not the latest release and not the benchmark archive version. The validation benchmark archive is versioned and deposited separately from the software, so the archive version and the software version move independently and are not interchangeable in a methods section. <a href="faq.html">Troubleshooting, versions and citation</a> carries the current identifiers.</p><h2 id="beyond">What provenance does not give you</h2><p>A complete record of what ran is not a claim that what ran was appropriate. Provenance makes an analysis auditable; it does not make it correct, and it is not a substitute for the judgements described in <a href="safeguards.html">What the workflow checks for you</a>.</p>`});

pages.push({slug:'codes',title:'Exit codes and statuses',group:'Reference',summary:'What each check status, command-line exit code, setup code and run state means, and what to do when you see it.',body:`<h2 id="statuses">Check statuses</h2>${grid(['Status','Meaning','In the interface','From <code>bulkseq check</code>'],[
['PASS','Nothing to report, or the check does not apply to this input route.','Continue.','Exit 0'],
['WARNING','An advisory finding that may limit interpretation.','Review it, then continue.','Exit 0'],
['REVIEW_REQUIRED','A finding that needs your judgement before you rely on the result.','Tick <em>I reviewed the phase checks marked Review required</em>, then continue.','Exit 0'],
['FAIL','A condition that prevents a correct analysis.','Start is disabled until the named cause is resolved and validation is repeated.','Exit 4'],
['STALE','The saved input validation no longer matches the current configuration, sample sheet or inputs.','Start is disabled until you validate again.','Not reported: only the interface tracks it.']])}<p>The overall status is the most severe finding, in the order FAIL, REVIEW_REQUIRED, WARNING, PASS; in the interface STALE ranks above FAIL. Three kinds of check can stop a workflow that is already running: a FAIL in check 00, project setup; anything but PASS in check 05, reference validation, on the FASTQ and SRA routes; and a failed microarray import, which records FAIL in checks 11 and 12, including when no probe resolves to one gene. Every other check records its status and the run carries on, so read Pre-run checks or <code>results/reports/sanity_checks.txt</code> when it finishes. <a href="checks.html">Pre-run and result checks</a> says what each numbered check tests.</p>${warning('<code>bulkseq run</code> does not evaluate these checks before it starts. In a script, run <code>bulkseq check</code> first and stop on exit 4.')+note('Some messages are advisories rather than statuses. The normalized-data message shown when column totals sit near one million, for example, appears when you import a count matrix and in the import log; it never becomes a check status.')}<h2 id="cli">Command line</h2>${grid(['Exit','Meaning','What to do'],[
['0','Success. For <code>check</code>, also when the worst finding is WARNING or REVIEW_REQUIRED.','Read the findings: exit 0 does not mean nothing needs review.'],
['1','An unexpected error, printed with a Python traceback.','Report it with the traceback and the command you ran.'],
['2','A usage error: no command given, or an invalid option or value.','Run <code>bulkseq --help</code> or <code>bulkseq COMMAND --help</code>.'],
['3','The path is not a project; <code>config/config.yaml</code> cannot be read or does not validate; <code>samples show</code> finds no readable sample sheet; or <code>run</code> could not refresh the project’s copy of the workflow.','Check the path given to <code>-C</code>. The message names the configuration field or the workflow problem.'],
['4','<code>check</code> found a FAIL, or the sample sheet is missing or unreadable.','Fix what the FAIL names, then run <code>check</code> again.'],
['5','The workflow run failed, including a failure the WSL launcher reported as success.','Read the log: the first <em>Error in rule</em> line names the failed step.'],
['130','Interrupted with Ctrl-C. The process tree is sent TERM, given up to eight seconds to release its lock, then sent KILL.','Continue with <code>bulkseq run --mode resume</code>.']])}<p><code>bulkseq --help</code> prints the same list, built from the constants the command returns, so the two cannot disagree. The command-line page covers <a href="cli.html#execute">running and resuming</a>.</p><h2 id="setup">Environment setup</h2><p>Check Environment writes the installer’s result to Show details / log, for example <em>WSL bioinformatics installer finished with exit code 3</em>.</p>${grid(['Exit','Meaning','What to do'],[
['0','Installed and verified.','Nothing.'],
['1','The platform is unsupported (the pipeline needs Linux on x86_64 or aarch64, natively or in WSL2); creating the environment failed from both the pinned lock and the floating specification; or verification still failed after the one automatic repair.','Read the last lines of the setup log: they name the failing step, package or probe.'],
['2','An invalid setup argument: a profile other than <code>core</code> or <code>full</code>, or <code>BULKSEQ_REBUILD</code> other than 0 or 1.','Only reachable when the script is run by hand. Run it again with a valid value.'],
['3','The package manager could not be installed: its download failed, or the Linux system has no <code>python3</code> and no downloader.','Follow the <em>ACTION REQUIRED</em> lines in the log, then click <em>Install / repair core environment</em> again.'],
['4','Another setup held the install lock for more than 30 minutes.','Make sure no other setup is running, then try again.']])}${note('A line mentioning 124 in the log marks one verification probe that timed out. It is not the installer’s exit code: verification then fails and the installer exits 1. If you stop setup yourself it ends early with a non-zero code; start it again when you are ready.')}<h2 id="run">A run in the interface</h2>${grid(['The run monitor shows','Meaning','What to do'],[
['Failed (exit code N)','The workflow stopped with an error.','Read the log: the first <em>Error in rule</em> line names the failed step.'],
['Failed — a rule reported an error (see the log)','A step failed although the launcher returned 0, which the WSL launcher can do. The monitor reads the log to catch it.','As above.'],
['Stopped','You stopped the run. It is marked with a WARNING status.','Resume continues from the completed steps.']])}<p>When the log shows R or Bioconductor packages failing to load, with <em>there is no package called</em>, <em>will not load in the bulkseq env</em> or <em>unable to load shared object</em>, the monitor offers to rebuild the analysis environment from its pinned lock. The command line reports the same failure as exit 5 and makes no offer.</p><h2 id="lookups">Public-data lookups</h2>${grid(['The message begins','Meaning','What to do'],[
['No single-platform series matrix found for GSE…','GEO holds no single-platform series matrix for this accession, as with a multi-platform series.','Pick a single-platform series. For an RNA-seq series, use the SRA and ENA route instead.'],
['Could not fetch GSE… from GEO (HTTP N)','GEO answered with another error.','Check the accession and retry later.'],
['Could not reach GEO for GSE…','There is no connection to GEO.','Check the network or proxy, then retry.'],
['GSE… has no linked SRA sequencing data','The series has no sequencing runs in SRA.','For a microarray series use <em>Fetch a GEO microarray series</em>; otherwise paste the SRA study or run accessions.'],
['ENA did not recognise the accession …','ENA knows no run, experiment, study, BioProject or GEO series by that accession.','Use an SRR, ERR or DRR run, an SRX experiment, an SRP or PRJNA study, or a GSE series. GSM samples are not accepted here.'],
['ENA query failed for … HTTP N','ENA answered with another error.','Retry later.'],
['Could not reach the ENA Portal API for …','There is no connection to ENA.','Check the network or proxy, then retry.']])}`});

// The hub: four labelled entry points, one for each kind of documentation.
const hubPage = pages.find(page => page.slug === 'index');
hubPage.title = 'BulkSeq Studio documentation';
hubPage.summary = 'Reproducible bulk RNA-seq and microarray analysis, from raw reads or processed inputs to a reviewable result.';
hubPage.body = `<p>BulkSeq Studio is a cross-platform desktop application that drives a transparent Snakemake workflow. Its interface configures read processing, gene quantification, differential expression and downstream interpretation; you can also enter later with counts, microarray intensities or a completed differential-expression table. A shortcut skips earlier work, but it does not reconstruct measurements you do not have.</p>${note(`This handbook documents release ${documentedVersion}, which corrects documentation, the command line and clipped empty-state messages in the interface, and leaves every analysis output as 0.32.0 produced it. The last release to change scientific output was 0.32.0: its corrections can change malformed-count handling, ambiguity-sensitive mapping and enrichment or cross-study selections, and synthetic regressions establish those contracts. Under ${documentedVersion} the bundled pasilla benchmark was rerun and reproduced its recorded counts and differential-expression table exactly; the Fusarium and rice benchmark results have not been rerun under 0.32.0 or ${documentedVersion}.`, `Release ${documentedVersion}`)+check('Read the <a href="faq.html#version-notices">version notices</a> before comparing results from different releases.')}<h2 id="where-to-start">Where to start</h2><div class="quadrants">${card('Tutorial','tutorial.html','Your first analysis','One complete run of a bundled four-sample study, with a known answer to check your result against. Start here if you have not used the application before.')}${card('How-to guides','guide.html','Do a particular thing','Install and set up, choose the input route that matches your data, build a sample sheet, define a comparison, run, and drive the same workflow from the command line.')}${card('Reference','checks.html','Look something up','What each check tests, what every status and exit code means, what a finished run writes, and the vocabulary the interface uses.')}${card('Explanation','safeguards.html','Understand why','What the workflow verifies on your behalf, how the differential-expression engines differ, how far a result reaches, and what a run records about itself.')}</div><h2 id="what-it-covers">What it covers</h2><p>Inputs are local FASTQ, SRA and ENA accessions, RNA-seq GEO series, raw count matrices, processed microarray matrices and imported differential-expression tables. Quantification uses STAR, HISAT2 or Salmon with featureCounts, STAR gene counts or tximport. Differential expression uses DESeq2 by default, with limma-voom and edgeR quasi-likelihood as alternatives and limma for microarrays. Interpretation covers directional GO and KEGG enrichment, custom gene sets, GSVA, STRING networks, publication figures and sortable reports.</p><h2 id="what-it-is-not">What it is not</h2><p>This is a bulk-expression analysis tool, not a single-cell workflow, a clinical diagnostic system or an automatic explanation of biological causation. A successful run means the computation completed; the study design, the quality checks and the interpretation still require your review.</p><h2 id="help">If something goes wrong</h2><p>Start with <a href="checks.html">the checks</a>, which name the problem more precisely than a failed run does, then <a href="faq.html">troubleshooting</a>. The <a href="glossary.html">glossary</a> defines the terms the interface uses.</p>`;

// Diátaxis layout. Order here is the order of the rails, the site map and the previous/next links.
const layout = [
  ['index', 'Home', ''],
  ['tutorial', 'Tutorial', ''],
  ['guide', 'How-to guides', 'Set up'],
  ['walkthrough', 'How-to guides', 'Set up'],
  ['inputs', 'How-to guides', 'Project and data'],
  ['project', 'How-to guides', 'Project and data'],
  ['microarray', 'How-to guides', 'Project and data'],
  ['imported-results', 'How-to guides', 'Project and data'],
  ['references', 'How-to guides', 'Analysis setup'],
  ['analysis', 'How-to guides', 'Analysis setup'],
  ['design', 'How-to guides', 'Analysis setup'],
  ['meta-analysis', 'How-to guides', 'Analysis setup'],
  ['resources', 'How-to guides', 'Analysis setup'],
  ['run', 'How-to guides', 'Run and automate'],
  ['cli', 'How-to guides', 'Run and automate'],
  ['checks', 'Reference', 'Checks'],
  ['outputs', 'Reference', 'Outputs'],
  ['enrichment', 'Reference', 'Outputs'],
  ['codes', 'Reference', 'Look-ups'],
  ['faq', 'Reference', 'Look-ups'],
  ['glossary', 'Reference', 'Look-ups'],
  ['safeguards', 'Explanation', ''],
  ['engines', 'Explanation', ''],
  ['interpreting', 'Explanation', ''],
  ['provenance', 'Explanation', ''],
];
{
  const placed = new Map(layout.map(([slug, section, part], order) => [slug, { section, part, order }]));
  const unplaced = pages.filter(page => !placed.has(page.slug)).map(page => page.slug);
  if (unplaced.length) throw new Error(`pages missing from the documentation layout: ${unplaced.join(', ')}`);
  const missing = [...placed.keys()].filter(slug => !pages.some(page => page.slug === slug));
  if (missing.length) throw new Error(`the documentation layout names pages that do not exist: ${missing.join(', ')}`);
  for (const page of pages) Object.assign(page, placed.get(page.slug));
  pages.sort((a, b) => a.order - b.order);
}
